  (5, '오늘 저녁은 파스타', '새벽 2시에 잠이 안 와서 글을 씁니다. 내일 출근인데 걱정이에요.', 'DAILY', '["아침", "습관"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17335 MINUTE)),
