  (6, '오늘 점심은 회사 구내식당', '구내식당 메뉴가 오늘은 돈까스였는데 역대급으로 맛있었습니다.', 'DAILY', '["브런치", "카페"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38242 MINUTE)),
  (7, '산책하다가 고양이 발견', '산책하다가 길고양이를 만났는데 다가와서 부비부비 해줬어요. 오늘의 하이라이트.', 'DAILY', '["베이킹", "취미"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26175 MINUTE)),
  (8, '편의점 신상 먹어봤다', '편의점에서 새로 나온 삼각김밥 먹어봤는데 생각보다 맛있어서 놀랐습니다.', 'DAILY', '["쇼핑", "패션"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23723 MINUTE)),
  (9, '오늘 택배 3개 왔다', '택배가 한꺼번에 와서 크리스마스 기분이에요. 쇼핑 중독인가...', 'DAILY', '["금요일", "기분"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14373 MINUTE)),
  (10, '잠이 안 와서 글 씀', '새벽 2시에 잠이 안 와서 글을 씁니다. 내일 출근인데 걱정이에요.', 'DAILY', '["월요일", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9065 MINUTE)),
  (1, '비 오는 날 감성', '비가 오니까 괜히 센치해지네요. 창밖 빗소리 들으면서 커피 한 잔.', 'DAILY', '["일상", "출근"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33392 MINUTE)),
  (2, '반려묘가 키보드 위에 올라왔다', '고양이가 제 노트북 키보드 위에 올라와서 코드를 작성해줬습니다. 컴파일은 안 되지만요.', 'DAILY', '["일상", "퇴근"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32343 MINUTE)),
  (3, '새벽 감성으로 글 쓰는 중', '새벽 감성으로 오랜만에 일기 같은 글을 써봅니다. 요즘 어떻게 지내고 계신가요?', 'DAILY', '["일상", "점심"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5957 MINUTE)),
  (4, '오늘 회의가 5개나 있었다', '회의가 하루에 5개라니... 집중 개발할 시간이 없습니다. 회의 줄여주세요.', 'DAILY', '["날씨", "기분"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3087 MINUTE)),
  (5, '퇴근하고 헬스장 갔다', '퇴근하고 헬스장에서 한 시간 운동했더니 스트레스가 풀립니다. 운동이 최고의 보약.', 'DAILY', '["반려동물", "힐링"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7185 MINUTE)),
  (6, '주말 브런치 카페 다녀왔다', '오늘도 평범한 하루를 보내고 있습니다. 특별한 일은 없지만 이런 평범함이 좋네요.', 'DAILY', '["주말", "계획"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10016 MINUTE)),
  (7, '집에서 빵 구워봤다', '출근길에 벚꽃이 피어있는 걸 봤어요. 봄이 오고 있나 봅니다. 기분이 좋아졌습니다.', 'DAILY', '["카페", "커피"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41120 MINUTE)),
  (8, '새 운동화 샀다', '퇴근하고 집에 와서 소파에 누웠더니 바로 잠들뻔했어요. 오늘도 고생했다 나 자신.', 'DAILY', '["일상", "감사"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10484 MINUTE)),
  (9, '드디어 금요일이다', '점심으로 김치찌개를 먹었는데 역시 한식이 최고입니다. 매콤하니 속이 따뜻해졌어요.', 'DAILY', '["출근", "지하철"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27666 MINUTE)),
  (10, '월요병이 심하다', '우리 집 강아지가 오늘 새 장난감을 받고 너무 좋아했어요. 보는 것만으로도 힐링됩니다.', 'DAILY', '["넷플릭스", "드라마"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39086 MINUTE)),
  (1, '점심시간이 왜 이렇게 짧지', '주말 계획을 세우는 중인데 넷플릭스 정주행이냐 나들이냐 고민 중입니다.', 'DAILY', '["요리", "자취"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4163 MINUTE)),
  (2, '오늘 커피 3잔째', '카페에서 아메리카노 한 잔 마시면서 멍때리는 중입니다. 이런 시간이 필요해요.', 'DAILY', '["청소", "자취"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25216 MINUTE)),
  (3, '동네 맛집 발견했다', '오늘 하루도 별일 없이 끝나려고 합니다. 무탈하게 보내는 게 최고인 것 같아요.', 'DAILY', '["친구", "모임"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25009 MINUTE)),
  (4, '출근길에 이어폰을 잃어버렸다', '지하철이 너무 만원이라 두 대를 보내고 탔습니다. 출근 시간이 점점 빨라지네요.', 'DAILY', '["키보드", "장비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39052 MINUTE)),
  (5, '오늘 하늘이 예쁘다', '드라마 새 시즌이 나와서 밤새 볼 뻔했어요. 내일 출근인데 큰일이다.', 'DAILY', '["아침", "습관"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30674 MINUTE)),
  (6, '퇴근 후 치킨 시켜먹는 중', '처음으로 감바스 만들어봤는데 생각보다 쉽고 맛있었어요. 자취 요리 레벨업!', 'DAILY', '["식사", "회사"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 34676 MINUTE)),
  (7, '주말에 등산 다녀왔다', '자취방 청소를 제대로 했더니 기분이 상쾌합니다. 깨끗한 집이 최고.', 'DAILY', '["고양이", "산책"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16476 MINUTE)),
  (8, '새로 시작한 취미 생활', '오랜만에 대학 동기를 만났는데 다들 열심히 살고 있더라고요. 나도 힘내야지.', 'DAILY', '["편의점", "후기"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36256 MINUTE)),
  (9, '오늘도 야근이다', '새로 산 기계식 키보드 타건감이 미쳤습니다. 타이핑하는 재미가 있어요.', 'DAILY', '["택배", "쇼핑"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 752 MINUTE)),
  (10, '자취 3년차의 깨달음', '일찍 일어나서 아침 먹고 출근하니까 하루가 길게 느껴집니다. 아침형 인간 도전!', 'DAILY', '["새벽", "감성"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7507 MINUTE)),
  (1, '반려동물과 함께하는 일상', '구내식당 메뉴가 오늘은 돈까스였는데 역대급으로 맛있었습니다.', 'DAILY', '["비", "감성"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35190 MINUTE)),
  (2, '오늘 좋은 일이 있었다', '산책하다가 길고양이를 만났는데 다가와서 부비부비 해줬어요. 오늘의 하이라이트.', 'DAILY', '["고양이", "일상"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17486 MINUTE)),
  (3, '퇴근길에 노을이 예뻤다', '편의점에서 새로 나온 삼각김밥 먹어봤는데 생각보다 맛있어서 놀랐습니다.', 'DAILY', '["새벽", "일기"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42006 MINUTE)),
