  (3, '새벽 감성으로 글 쓰는 중', '새벽 감성으로 오랜만에 일기 같은 글을 써봅니다. 요즘 어떻게 지내고 계신가요?', 'DAILY', '["새벽", "일기"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23788 MINUTE)),
  (4, '오늘 회의가 5개나 있었다', '회의가 하루에 5개라니... 집중 개발할 시간이 없습니다. 회의 줄여주세요.', 'DAILY', '["회의", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20153 MINUTE)),
  (5, '퇴근하고 헬스장 갔다', '퇴근하고 헬스장에서 한 시간 운동했더니 스트레스가 풀립니다. 운동이 최고의 보약.', 'DAILY', '["운동", "헬스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15692 MINUTE)),
  (6, '주말 브런치 카페 다녀왔다', '오늘도 평범한 하루를 보내고 있습니다. 특별한 일은 없지만 이런 평범함이 좋네요.', 'DAILY', '["브런치", "카페"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3796 MINUTE)),
  (7, '집에서 빵 구워봤다', '출근길에 벚꽃이 피어있는 걸 봤어요. 봄이 오고 있나 봅니다. 기분이 좋아졌습니다.', 'DAILY', '["베이킹", "취미"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15785 MINUTE)),
  (8, '새 운동화 샀다', '퇴근하고 집에 와서 소파에 누웠더니 바로 잠들뻔했어요. 오늘도 고생했다 나 자신.', 'DAILY', '["쇼핑", "패션"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37182 MINUTE)),
  (9, '드디어 금요일이다', '점심으로 김치찌개를 먹었는데 역시 한식이 최고입니다. 매콤하니 속이 따뜻해졌어요.', 'DAILY', '["금요일", "기분"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5161 MINUTE)),
  (10, '월요병이 심하다', '우리 집 강아지가 오늘 새 장난감을 받고 너무 좋아했어요. 보는 것만으로도 힐링됩니다.', 'DAILY', '["월요일", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5613 MINUTE)),
  (1, '점심시간이 왜 이렇게 짧지', '주말 계획을 세우는 중인데 넷플릭스 정주행이냐 나들이냐 고민 중입니다.', 'DAILY', '["일상", "출근"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31849 MINUTE)),
  (2, '오늘 커피 3잔째', '카페에서 아메리카노 한 잔 마시면서 멍때리는 중입니다. 이런 시간이 필요해요.', 'DAILY', '["일상", "퇴근"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4535 MINUTE)),
  (3, '동네 맛집 발견했다', '오늘 하루도 별일 없이 끝나려고 합니다. 무탈하게 보내는 게 최고인 것 같아요.', 'DAILY', '["일상", "점심"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 34911 MINUTE)),
  (4, '출근길에 이어폰을 잃어버렸다', '지하철이 너무 만원이라 두 대를 보내고 탔습니다. 출근 시간이 점점 빨라지네요.', 'DAILY', '["날씨", "기분"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8241 MINUTE)),
  (5, '오늘 하늘이 예쁘다', '드라마 새 시즌이 나와서 밤새 볼 뻔했어요. 내일 출근인데 큰일이다.', 'DAILY', '["반려동물", "힐링"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8414 MINUTE)),
  (6, '퇴근 후 치킨 시켜먹는 중', '처음으로 감바스 만들어봤는데 생각보다 쉽고 맛있었어요. 자취 요리 레벨업!', 'DAILY', '["주말", "계획"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31148 MINUTE)),
  (7, '주말에 등산 다녀왔다', '자취방 청소를 제대로 했더니 기분이 상쾌합니다. 깨끗한 집이 최고.', 'DAILY', '["카페", "커피"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36031 MINUTE)),
  (8, '새로 시작한 취미 생활', '오랜만에 대학 동기를 만났는데 다들 열심히 살고 있더라고요. 나도 힘내야지.', 'DAILY', '["일상", "감사"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10821 MINUTE)),
  (9, '오늘도 야근이다', '새로 산 기계식 키보드 타건감이 미쳤습니다. 타이핑하는 재미가 있어요.', 'DAILY', '["출근", "지하철"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17370 MINUTE)),
  (10, '자취 3년차의 깨달음', '일찍 일어나서 아침 먹고 출근하니까 하루가 길게 느껴집니다. 아침형 인간 도전!', 'DAILY', '["넷플릭스", "드라마"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 34581 MINUTE)),
  (1, '반려동물과 함께하는 일상', '구내식당 메뉴가 오늘은 돈까스였는데 역대급으로 맛있었습니다.', 'DAILY', '["요리", "자취"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39753 MINUTE)),
  (2, '오늘 좋은 일이 있었다', '산책하다가 길고양이를 만났는데 다가와서 부비부비 해줬어요. 오늘의 하이라이트.', 'DAILY', '["청소", "자취"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27730 MINUTE)),
  (3, '퇴근길에 노을이 예뻤다', '편의점에서 새로 나온 삼각김밥 먹어봤는데 생각보다 맛있어서 놀랐습니다.', 'DAILY', '["친구", "모임"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13880 MINUTE)),
  (4, '주말 알바 끝나고 쉬는 중', '택배가 한꺼번에 와서 크리스마스 기분이에요. 쇼핑 중독인가...', 'DAILY', '["키보드", "장비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35343 MINUTE)),
  (5, '오늘 저녁은 파스타', '새벽 2시에 잠이 안 와서 글을 씁니다. 내일 출근인데 걱정이에요.', 'DAILY', '["아침", "습관"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13182 MINUTE)),
  (6, '새벽에 라면 끓여먹는 중', '비가 오니까 괜히 센치해지네요. 창밖 빗소리 들으면서 커피 한 잔.', 'DAILY', '["식사", "회사"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20428 MINUTE)),
  (7, '일요일 오후의 여유', '고양이가 제 노트북 키보드 위에 올라와서 코드를 작성해줬습니다. 컴파일은 안 되지만요.', 'DAILY', '["고양이", "산책"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26148 MINUTE)),
  (8, '평일 낮에 카페 와봤다', '새벽 감성으로 오랜만에 일기 같은 글을 써봅니다. 요즘 어떻게 지내고 계신가요?', 'DAILY', '["편의점", "후기"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42590 MINUTE)),
  (9, '오늘 기분이 좋다', '회의가 하루에 5개라니... 집중 개발할 시간이 없습니다. 회의 줄여주세요.', 'DAILY', '["택배", "쇼핑"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 24472 MINUTE)),
  (10, '집 앞 공원에서 산책', '퇴근하고 헬스장에서 한 시간 운동했더니 스트레스가 풀립니다. 운동이 최고의 보약.', 'DAILY', '["새벽", "감성"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28711 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, '이직할까 말까 고민 중입니다', '현재 3년차인데 이직을 고민하고 있습니다. 연봉은 괜찮은데 성장이 안 되는 느낌이에요. 비슷한 경험 있으신 분 조언 부탁드립니다.', 'ADVICE', '["이직", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33919 MINUTE)),
  (2, '연애 상담 좀 부탁드려요', '사귄 지 2년 된 연인이 있는데 요즘 대화가 줄었어요. 권태기인 건지 진심으로 식은 건지 모르겠습니다.', 'ADVICE', '["연애", "상담"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29588 MINUTE)),
  (3, '직장 상사와의 갈등', '직장 상사가 매일 야근을 강요합니다. 거절하면 인사 평가에 불이익을 준다고 하는데 어떻게 해야 할까요?', 'ADVICE', '["직장", "갈등"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7930 MINUTE)),
  (4, '진로를 못 정하겠어요', '문과 졸업했는데 코딩을 배워서 개발자로 전직하고 싶어요. 가능한 건가요? 어디서부터 시작해야 할지 모르겠어요.', 'ADVICE', '["진로", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16246 MINUTE)),
  (5, '인간관계가 너무 힘듭니다', '주변 사람들과 자꾸 비교하게 되면서 인간관계가 힘들어졌어요. 어떻게 하면 건강한 관계를 유지할 수 있을까요?', 'ADVICE', '["인간관계", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14725 MINUTE)),
  (6, '건강이 안 좋아졌어요', '최근에 건강검진에서 이상 소견이 나왔습니다. 병원을 더 가봐야 하는데 무섭고 걱정됩니다.', 'ADVICE', '["건강", "걱정"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4196 MINUTE)),
  (7, '자취 시작하는데 조언 부탁', '첫 자취를 시작하려는데 뭘 준비해야 할지 감이 안 잡혀요. 경험자분들 필수템 알려주세요.', 'ADVICE', '["자취", "준비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22156 MINUTE)),
  (8, '대학원 진학 고민', '학부 졸업 후 대학원에 갈지 취업할지 고민 중입니다. 석사가 실무에서 얼마나 도움이 될까요?', 'ADVICE', '["대학원", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1378 MINUTE)),
  (9, '번아웃이 온 것 같아요', '요즘 일에 의욕이 전혀 없고 출근만 생각하면 우울해져요. 번아웃인 것 같은데 어떻게 극복하셨나요?', 'ADVICE', '["번아웃", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38555 MINUTE)),
  (10, '적금 깨야 할까요', '적금 만기 전인데 급하게 돈이 필요한 상황이에요. 해약하면 이자가 아까운데 다른 방법이 있을까요?', 'ADVICE', '["재테크", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36301 MINUTE)),
  (1, '친구 관계 정리하고 싶어요', '오래된 친구인데 만날 때마다 에너지가 소모돼요. 관계를 정리해도 될까요?', 'ADVICE', '["친구", "관계"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15080 MINUTE)),
  (2, '부모님과 의견 차이', '부모님이 원하는 진로와 제가 원하는 진로가 달라서 매일 갈등입니다.', 'ADVICE', '["가족", "갈등"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38564 MINUTE)),
  (3, '결혼 준비 스트레스', '결혼 준비하면서 양가 의견 조율이 너무 힘듭니다. 작은 것 하나에도 갈등이 생겨요.', 'ADVICE', '["결혼", "준비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14432 MINUTE)),
  (4, '직장 내 따돌림', '팀에서 저만 빼고 점심을 먹더라고요. 직장 내 따돌림인 것 같은데 어떻게 대처해야 할까요?', 'ADVICE', '["직장", "따돌림"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 471 MINUTE)),
  (5, '우울감이 지속되고 있어요', '몇 달째 우울한 기분이 계속됩니다. 전문 상담을 받아야 할까요?', 'ADVICE', '["우울", "상담"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4652 MINUTE)),
  (6, '이사를 해야 하는데 고민', '전세 만기인데 집값이 올라서 이사를 가야 할 것 같아요. 어디로 가야 할지 고민이에요.', 'ADVICE', '["이사", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41359 MINUTE)),
  (7, '연봉 협상 어떻게 하나요', '이직 제안을 받았는데 연봉 협상을 어떻게 해야 할지 모르겠어요. 현재보다 20% 올려달라고 해도 될까요?', 'ADVICE', '["연봉", "협상"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3858 MINUTE)),
  (8, '재테크 시작하고 싶은데', '사회초년생인데 재테크를 시작하고 싶어요. 적금 말고 다른 방법이 있을까요?', 'ADVICE', '["재테크", "사회초년생"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15003 MINUTE)),
  (9, '다이어트 의지가 안 생겨요', '매번 다이어트를 시작하는데 3일도 못 가서 포기합니다. 의지력 키우는 방법이 있나요?', 'ADVICE', '["다이어트", "의지"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4417 MINUTE)),
  (10, '수면 패턴이 너무 안 좋아요', '수면 패턴이 완전히 망가졌어요. 새벽 4시에 자고 점심에 일어나는 생활을 고치고 싶습니다.', 'ADVICE', '["수면", "건강"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 2058 MINUTE)),
  (1, '자존감이 낮아서 힘들어요', '자존감이 너무 낮아서 뭘 해도 자신이 없어요. 어떻게 하면 자존감을 높일 수 있을까요?', 'ADVICE', '["자존감", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21654 MINUTE)),
  (2, '새 직장에 적응이 안 돼요', '새 직장에 온 지 한 달인데 아직도 적응이 안 됩니다. 다들 적응하는 데 얼마나 걸렸나요?', 'ADVICE', '["신입", "적응"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4643 MINUTE)),
  (3, '동료와의 업무 갈등', '같은 팀 동료가 제 아이디어를 자기 것처럼 발표했어요. 어떻게 대응해야 할까요?', 'ADVICE', '["동료", "갈등"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33695 MINUTE)),
  (4, '가족 간 금전 문제', '가족에게 돈을 빌려줬는데 안 갚아요. 얘기를 꺼내기가 어렵습니다.', 'ADVICE', '["가족", "금전"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15597 MINUTE)),
  (5, '취미를 찾고 싶어요', '퇴근 후 시간이 많은데 뭘 해야 할지 모르겠어요. 추천할 만한 취미 있나요?', 'ADVICE', '["취미", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18250 MINUTE)),
  (6, '혼자 사는 게 외로워요', '현재 3년차인데 이직을 고민하고 있습니다. 연봉은 괜찮은데 성장이 안 되는 느낌이에요. 비슷한 경험 있으신 분 조언 부탁드립니다.', 'ADVICE', '["외로움", "혼자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31812 MINUTE)),
  (7, '30대 커리어 전환 고민', '사귄 지 2년 된 연인이 있는데 요즘 대화가 줄었어요. 권태기인 건지 진심으로 식은 건지 모르겠습니다.', 'ADVICE', '["커리어", "전환"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14040 MINUTE)),
  (8, '대인기피증이 있는 것 같아요', '직장 상사가 매일 야근을 강요합니다. 거절하면 인사 평가에 불이익을 준다고 하는데 어떻게 해야 할까요?', 'ADVICE', '["사회생활", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35339 MINUTE)),
  (9, '미래가 불안합니다', '문과 졸업했는데 코딩을 배워서 개발자로 전직하고 싶어요. 가능한 건가요? 어디서부터 시작해야 할지 모르겠어요.', 'ADVICE', '["미래", "불안"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8671 MINUTE)),
  (10, '상사에게 거절하는 법', '주변 사람들과 자꾸 비교하게 되면서 인간관계가 힘들어졌어요. 어떻게 하면 건강한 관계를 유지할 수 있을까요?', 'ADVICE', '["직장", "상사"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37423 MINUTE)),
  (1, '퇴사하고 프리랜서 할까요', '최근에 건강검진에서 이상 소견이 나왔습니다. 병원을 더 가봐야 하는데 무섭고 걱정됩니다.', 'ADVICE', '["이직", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37762 MINUTE)),
  (2, '친구가 돈을 빌려달라는데', '첫 자취를 시작하려는데 뭘 준비해야 할지 감이 안 잡혀요. 경험자분들 필수템 알려주세요.', 'ADVICE', '["연애", "상담"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30976 MINUTE)),
  (3, '학자금 대출 상환 고민', '학부 졸업 후 대학원에 갈지 취업할지 고민 중입니다. 석사가 실무에서 얼마나 도움이 될까요?', 'ADVICE', '["직장", "갈등"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15925 MINUTE)),
  (4, '룸메이트와의 갈등', '요즘 일에 의욕이 전혀 없고 출근만 생각하면 우울해져요. 번아웃인 것 같은데 어떻게 극복하셨나요?', 'ADVICE', '["진로", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30996 MINUTE)),
  (5, '회사 문화가 안 맞아요', '적금 만기 전인데 급하게 돈이 필요한 상황이에요. 해약하면 이자가 아까운데 다른 방법이 있을까요?', 'ADVICE', '["인간관계", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26677 MINUTE)),
  (6, '운동을 시작하고 싶은데', '오래된 친구인데 만날 때마다 에너지가 소모돼요. 관계를 정리해도 될까요?', 'ADVICE', '["건강", "걱정"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12478 MINUTE)),
  (7, 'SNS 중독인 것 같아요', '부모님이 원하는 진로와 제가 원하는 진로가 달라서 매일 갈등입니다.', 'ADVICE', '["자취", "준비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6181 MINUTE)),
  (8, '사회생활이 힘든 신입', '결혼 준비하면서 양가 의견 조율이 너무 힘듭니다. 작은 것 하나에도 갈등이 생겨요.', 'ADVICE', '["대학원", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6352 MINUTE)),
  (9, '공부 집중이 안 돼요', '팀에서 저만 빼고 점심을 먹더라고요. 직장 내 따돌림인 것 같은데 어떻게 대처해야 할까요?', 'ADVICE', '["번아웃", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 43187 MINUTE)),
  (10, '자격증 뭐 따면 좋을까요', '몇 달째 우울한 기분이 계속됩니다. 전문 상담을 받아야 할까요?', 'ADVICE', '["재테크", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28249 MINUTE)),
  (1, '직장과 공부 병행이 힘들어요', '전세 만기인데 집값이 올라서 이사를 가야 할 것 같아요. 어디로 가야 할지 고민이에요.', 'ADVICE', '["친구", "관계"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23219 MINUTE)),
  (2, '연인과 장거리 연애 중', '이직 제안을 받았는데 연봉 협상을 어떻게 해야 할지 모르겠어요. 현재보다 20% 올려달라고 해도 될까요?', 'ADVICE', '["가족", "갈등"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27759 MINUTE)),
  (3, '나이 들수록 친구가 줄어요', '사회초년생인데 재테크를 시작하고 싶어요. 적금 말고 다른 방법이 있을까요?', 'ADVICE', '["결혼", "준비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26941 MINUTE)),
  (4, '직장에서 인정받고 싶어요', '매번 다이어트를 시작하는데 3일도 못 가서 포기합니다. 의지력 키우는 방법이 있나요?', 'ADVICE', '["직장", "따돌림"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30606 MINUTE)),
  (5, '건강 검진 결과가 안 좋아요', '수면 패턴이 완전히 망가졌어요. 새벽 4시에 자고 점심에 일어나는 생활을 고치고 싶습니다.', 'ADVICE', '["우울", "상담"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3550 MINUTE)),
  (6, '목표를 세워도 지키지 못해요', '자존감이 너무 낮아서 뭘 해도 자신이 없어요. 어떻게 하면 자존감을 높일 수 있을까요?', 'ADVICE', '["이사", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42824 MINUTE)),
  (7, '스트레스 해소법이 필요해요', '새 직장에 온 지 한 달인데 아직도 적응이 안 됩니다. 다들 적응하는 데 얼마나 걸렸나요?', 'ADVICE', '["연봉", "협상"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42348 MINUTE)),
  (8, '내성적인 성격이 고민이에요', '같은 팀 동료가 제 아이디어를 자기 것처럼 발표했어요. 어떻게 대응해야 할까요?', 'ADVICE', '["재테크", "사회초년생"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6449 MINUTE)),
  (9, '이직 면접 준비 어떻게 하나요', '가족에게 돈을 빌려줬는데 안 갚아요. 얘기를 꺼내기가 어렵습니다.', 'ADVICE', '["다이어트", "의지"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3972 MINUTE)),
  (10, '관계에서 경계를 못 세워요', '퇴근 후 시간이 많은데 뭘 해야 할지 모르겠어요. 추천할 만한 취미 있나요?', 'ADVICE', '["수면", "건강"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26386 MINUTE));
