  (5, '회사 문화가 안 맞아요', '적금 만기 전인데 급하게 돈이 필요한 상황이에요. 해약하면 이자가 아까운데 다른 방법이 있을까요?', 'ADVICE', '["취미", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17380 MINUTE)),
  (6, '운동을 시작하고 싶은데', '오래된 친구인데 만날 때마다 에너지가 소모돼요. 관계를 정리해도 될까요?', 'ADVICE', '["외로움", "혼자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29819 MINUTE)),
  (7, 'SNS 중독인 것 같아요', '부모님이 원하는 진로와 제가 원하는 진로가 달라서 매일 갈등입니다.', 'ADVICE', '["커리어", "전환"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18694 MINUTE)),
  (8, '사회생활이 힘든 신입', '결혼 준비하면서 양가 의견 조율이 너무 힘듭니다. 작은 것 하나에도 갈등이 생겨요.', 'ADVICE', '["사회생활", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27722 MINUTE)),
  (9, '공부 집중이 안 돼요', '팀에서 저만 빼고 점심을 먹더라고요. 직장 내 따돌림인 것 같은데 어떻게 대처해야 할까요?', 'ADVICE', '["미래", "불안"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36422 MINUTE)),
  (10, '자격증 뭐 따면 좋을까요', '몇 달째 우울한 기분이 계속됩니다. 전문 상담을 받아야 할까요?', 'ADVICE', '["직장", "상사"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31894 MINUTE)),
  (1, '직장과 공부 병행이 힘들어요', '전세 만기인데 집값이 올라서 이사를 가야 할 것 같아요. 어디로 가야 할지 고민이에요.', 'ADVICE', '["이직", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10144 MINUTE)),
  (2, '연인과 장거리 연애 중', '이직 제안을 받았는데 연봉 협상을 어떻게 해야 할지 모르겠어요. 현재보다 20% 올려달라고 해도 될까요?', 'ADVICE', '["연애", "상담"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12445 MINUTE)),
  (3, '나이 들수록 친구가 줄어요', '사회초년생인데 재테크를 시작하고 싶어요. 적금 말고 다른 방법이 있을까요?', 'ADVICE', '["직장", "갈등"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19445 MINUTE)),
  (4, '직장에서 인정받고 싶어요', '매번 다이어트를 시작하는데 3일도 못 가서 포기합니다. 의지력 키우는 방법이 있나요?', 'ADVICE', '["진로", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14267 MINUTE)),
  (5, '건강 검진 결과가 안 좋아요', '수면 패턴이 완전히 망가졌어요. 새벽 4시에 자고 점심에 일어나는 생활을 고치고 싶습니다.', 'ADVICE', '["인간관계", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3832 MINUTE)),
  (6, '목표를 세워도 지키지 못해요', '자존감이 너무 낮아서 뭘 해도 자신이 없어요. 어떻게 하면 자존감을 높일 수 있을까요?', 'ADVICE', '["건강", "걱정"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37957 MINUTE)),
  (7, '스트레스 해소법이 필요해요', '새 직장에 온 지 한 달인데 아직도 적응이 안 됩니다. 다들 적응하는 데 얼마나 걸렸나요?', 'ADVICE', '["자취", "준비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35533 MINUTE)),
  (8, '내성적인 성격이 고민이에요', '같은 팀 동료가 제 아이디어를 자기 것처럼 발표했어요. 어떻게 대응해야 할까요?', 'ADVICE', '["대학원", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3994 MINUTE)),
  (9, '이직 면접 준비 어떻게 하나요', '가족에게 돈을 빌려줬는데 안 갚아요. 얘기를 꺼내기가 어렵습니다.', 'ADVICE', '["번아웃", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20552 MINUTE)),
  (10, '관계에서 경계를 못 세워요', '퇴근 후 시간이 많은데 뭘 해야 할지 모르겠어요. 추천할 만한 취미 있나요?', 'ADVICE', '["재테크", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3746 MINUTE));
