  (10, '자격증 뭐 따면 좋을까요', '몇 달째 우울한 기분이 계속됩니다. 전문 상담을 받아야 할까요?', 'ADVICE', '["수면", "건강"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20720 MINUTE)),
  (1, '직장과 공부 병행이 힘들어요', '전세 만기인데 집값이 올라서 이사를 가야 할 것 같아요. 어디로 가야 할지 고민이에요.', 'ADVICE', '["자존감", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4754 MINUTE)),
  (2, '연인과 장거리 연애 중', '이직 제안을 받았는데 연봉 협상을 어떻게 해야 할지 모르겠어요. 현재보다 20% 올려달라고 해도 될까요?', 'ADVICE', '["신입", "적응"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 610 MINUTE)),
  (3, '나이 들수록 친구가 줄어요', '사회초년생인데 재테크를 시작하고 싶어요. 적금 말고 다른 방법이 있을까요?', 'ADVICE', '["동료", "갈등"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30034 MINUTE)),
  (4, '직장에서 인정받고 싶어요', '매번 다이어트를 시작하는데 3일도 못 가서 포기합니다. 의지력 키우는 방법이 있나요?', 'ADVICE', '["가족", "금전"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40708 MINUTE)),
  (5, '건강 검진 결과가 안 좋아요', '수면 패턴이 완전히 망가졌어요. 새벽 4시에 자고 점심에 일어나는 생활을 고치고 싶습니다.', 'ADVICE', '["취미", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36896 MINUTE)),
  (6, '목표를 세워도 지키지 못해요', '자존감이 너무 낮아서 뭘 해도 자신이 없어요. 어떻게 하면 자존감을 높일 수 있을까요?', 'ADVICE', '["외로움", "혼자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6552 MINUTE)),
  (7, '스트레스 해소법이 필요해요', '새 직장에 온 지 한 달인데 아직도 적응이 안 됩니다. 다들 적응하는 데 얼마나 걸렸나요?', 'ADVICE', '["커리어", "전환"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4801 MINUTE)),
  (8, '내성적인 성격이 고민이에요', '같은 팀 동료가 제 아이디어를 자기 것처럼 발표했어요. 어떻게 대응해야 할까요?', 'ADVICE', '["사회생활", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35234 MINUTE)),
  (9, '이직 면접 준비 어떻게 하나요', '가족에게 돈을 빌려줬는데 안 갚아요. 얘기를 꺼내기가 어렵습니다.', 'ADVICE', '["미래", "불안"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13969 MINUTE)),
  (10, '관계에서 경계를 못 세워요', '퇴근 후 시간이 많은데 뭘 해야 할지 모르겠어요. 추천할 만한 취미 있나요?', 'ADVICE', '["직장", "상사"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33153 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, '이직할까 말까 고민 중입니다', '현재 3년차인데 이직을 고민하고 있습니다. 연봉은 괜찮은데 성장이 안 되는 느낌이에요. 비슷한 경험 있으신 분 조언 부탁드립니다.', 'ADVICE', '["이직", "고민"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17380 MINUTE)),
