  (10, '체육대회 레전드', '팀장님한테 보내야 할 카톡을 여자친구한테 보냈는데 ''네 알겠습니다 팀장님'' 이라고... 여친이 ''팀장님?ㅋㅋ'' 하고 넘어가줬어요.', 'HUMOR', '["아재개그", "유머"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4585 MINUTE)),
  (1, '동물원에서 있었던 일', '새벽 3시에 치킨 시키고 후회하면서 먹었는데 맛있어서 다시 후회가 사라졌습니다.', 'HUMOR', '["웃김", "카페"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21639 MINUTE)),
  (2, '오늘의 아재개그', '고양이가 제 화분을 다 엎어놓고 제 베개 위에서 자고 있었어요. 눈이 마주쳤는데 하품을 하더라고요.', 'HUMOR', '["웃김", "개발"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40839 MINUTE)),
  (3, '카페 알바 손님 레전드', '술자리에서 선배가 ''나 원래 주량이 소주 3병이야''라고 했는데 소주 1병에 뻗었습니다.', 'HUMOR', '["택배", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20572 MINUTE)),
  (4, '자취방 벌레 퇴치 대작전', '지하철에서 할아버지 두 분이 와이파이 비밀번호에 대해 열띤 토론을 하고 계셨어요. 결국 손자에게 전화하심.', 'HUMOR', '["부모님", "카톡"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8167 MINUTE)),
  (5, '친구의 어이없는 실수', '배달 리뷰에 ''짜장면에서 머리카락이 나왔는데 제 머리카락이었습니다. 죄송합니다.'' 별 다섯 개.', 'HUMOR', '["직장", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19681 MINUTE)),
  (6, '부장님의 반전 매력', '회사 단톡방에 여친한테 보낼 하트를 잘못 보냈습니다. 팀장님이 하트로 답해주셨어요.', 'HUMOR', '["소개팅", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33234 MINUTE)),
  (7, '음식 배달 사고', '아버지한테 스마트폰 가르쳐드렸는데 유튜브에서 ''숏츠''를 발견하시고 3시간째 보고 계세요. 제가 만든 괴물...', 'HUMOR', '["자취", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20269 MINUTE)),
  (8, '단톡방 폭탄 발언', '편의점 알바할 때 손님이 ''이거 얼마예요?'' 하길래 바코드 찍었더니 ''가격이 0원입니다'' 나왔어요. 시스템 오류였는데 손님 눈이 반짝반짝.', 'HUMOR', '["코드리뷰", "개발"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26764 MINUTE)),
  (9, '동기의 황당한 변명', '엘리베이터에 나 혼자인 줄 알고 방귀를 뀌었는데 문이 열리면서 사람이 쏟아져 들어왔습니다. 그날 계단으로 다녔어요.', 'HUMOR', '["배달", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21376 MINUTE)),
  (10, '오늘도 웃긴 하루', '회의 중에 폰에서 알람이 울렸는데 알람 제목이 ''퇴근하자!!''였습니다. 다 같이 웃었어요.', 'HUMOR', '["반려동물", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26371 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, '오늘 카페에서 있었던 일', '카페에서 아이스 아메리카노를 주문했는데 핫으로 나왔어요. 항의하려니까 제 앞 손님이 핫을 시켰는데 아이스가 나온 거였음 ㅋㅋㅋ 바뀐 거였다', 'HUMOR', '["회식", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19376 MINUTE)),
  (2, '우리 팀 신입의 전설적인 실수', '신입이 git push --force를 main 브랜치에 했습니다. 팀 전체가 멘붕... 그래도 당일 복구했어요. 이후 branch protection이 생겼습니다.', 'HUMOR', '["면접", "긴장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36333 MINUTE)),
  (3, '택배 기사님과의 대화', '택배 기사님이 문 앞에 놓고 가시면서 사진을 찍어주셨는데 우리 집 고양이가 택배 위에 앉아있는 사진이었어요 ㅋㅋ', 'HUMOR', '["어르신", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8341 MINUTE)),
  (4, '어머니의 카톡 오타', '어머니가 카톡으로 ''밥 먹었니'' 대신 ''밤 먹었니'' 라고 보내셨는데, 아버지가 옆에서 ''밤이면 밤마다'' 하셔서 어머니한테 혼남 ㅋㅋ', 'HUMOR', '["중고거래", "레전드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12572 MINUTE)),
  (5, '회사에서 방귀 참다가 생긴 일', '회의 중에 배에서 꼬르륵 소리가 나서 기침으로 위장했는데, 팀장님이 ''감기 걸렸어? 오늘 일찍 퇴근해'' 라고 하셔서 일찍 퇴근했습니다. 럭키!', 'HUMOR', '["오타", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27554 MINUTE)),
  (6, '소개팅 역대급 썰', '소개팅에서 상대방이 제 회사 동기였습니다. 서로 당황해서 모르는 척 했는데 다음날 회사에서 마주쳐서 더 어색... 지금은 잘 사귀고 있어요 ㅎ', 'HUMOR', '["새벽", "배달"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 24847 MINUTE)),
  (7, '자취생의 냉장고 발굴기', '냉장고 안쪽에서 작년에 넣어둔 반찬통을 발견했는데 뚜껑을 열자마자 후회했습니다. 그냥 통째로 버렸어요...', 'HUMOR', '["고양이", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 11405 MINUTE)),
  (8, '코드 리뷰에서 발견한 주석', '코드 리뷰하다가 주석에 // TODO: 이거 왜 동작하는지 모름 을 발견했습니다. 작성자는 이미 퇴사한 사람이었어요.', 'HUMOR', '["술자리", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40338 MINUTE)),
  (9, '오늘의 웃긴 배달 리뷰', '배달 리뷰에 ''맛있어서 화가 납니다. 다이어트 중이었거든요.'' 라고 써있어서 웃었습니다.', 'HUMOR', '["지하철", "목격"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37296 MINUTE)),
  (10, '강아지가 택배 상자를 열었다', '택배가 와서 현관에 두었는데 우리 강아지가 상자를 다 찢어놓았어요. 안에 강아지 간식이 들어있었는데 이미 반은 먹은 상태...', 'HUMOR', '["배달", "레전드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19723 MINUTE)),
