  (8, '새 후배의 귀여운 실수', '할머니께서 키오스크로 주문하시는데 화면을 누르면서 ''여보세요?'' 하셨어요. 할머니 귀여우셔...', 'HUMOR', '["술자리", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20343 MINUTE)),
  (9, '운전면허 시험 썰', '중고나라에서 에어팟 팔려고 올렸더니 ''삼만원에 안 되냐''고 해서 안 된다고 했더니 ''그럼 이만원은?''이라는 답장이 왔습니다.', 'HUMOR', '["지하철", "목격"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14722 MINUTE)),
  (10, '체육대회 레전드', '팀장님한테 보내야 할 카톡을 여자친구한테 보냈는데 ''네 알겠습니다 팀장님'' 이라고... 여친이 ''팀장님?ㅋㅋ'' 하고 넘어가줬어요.', 'HUMOR', '["배달", "레전드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13050 MINUTE)),
  (1, '동물원에서 있었던 일', '새벽 3시에 치킨 시키고 후회하면서 먹었는데 맛있어서 다시 후회가 사라졌습니다.', 'HUMOR', '["단톡방", "실수"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9656 MINUTE)),
  (2, '오늘의 아재개그', '고양이가 제 화분을 다 엎어놓고 제 베개 위에서 자고 있었어요. 눈이 마주쳤는데 하품을 하더라고요.', 'HUMOR', '["부모님", "스마트폰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1600 MINUTE)),
  (3, '카페 알바 손님 레전드', '술자리에서 선배가 ''나 원래 주량이 소주 3병이야''라고 했는데 소주 1병에 뻗었습니다.', 'HUMOR', '["알바", "손님"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3028 MINUTE)),
  (4, '자취방 벌레 퇴치 대작전', '지하철에서 할아버지 두 분이 와이파이 비밀번호에 대해 열띤 토론을 하고 계셨어요. 결국 손자에게 전화하심.', 'HUMOR', '["엘리베이터", "사건"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16046 MINUTE)),
  (5, '친구의 어이없는 실수', '배달 리뷰에 ''짜장면에서 머리카락이 나왔는데 제 머리카락이었습니다. 죄송합니다.'' 별 다섯 개.', 'HUMOR', '["회의", "해프닝"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31138 MINUTE)),
  (6, '부장님의 반전 매력', '회사 단톡방에 여친한테 보낼 하트를 잘못 보냈습니다. 팀장님이 하트로 답해주셨어요.', 'HUMOR', '["카톡", "실수"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40060 MINUTE)),
  (7, '음식 배달 사고', '아버지한테 스마트폰 가르쳐드렸는데 유튜브에서 ''숏츠''를 발견하시고 3시간째 보고 계세요. 제가 만든 괴물...', 'HUMOR', '["택시", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4772 MINUTE)),
  (8, '단톡방 폭탄 발언', '편의점 알바할 때 손님이 ''이거 얼마예요?'' 하길래 바코드 찍었더니 ''가격이 0원입니다'' 나왔어요. 시스템 오류였는데 손님 눈이 반짝반짝.', 'HUMOR', '["개발자", "유머"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29846 MINUTE)),
  (9, '동기의 황당한 변명', '엘리베이터에 나 혼자인 줄 알고 방귀를 뀌었는데 문이 열리면서 사람이 쏟아져 들어왔습니다. 그날 계단으로 다녔어요.', 'HUMOR', '["리뷰", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27160 MINUTE)),
  (10, '오늘도 웃긴 하루', '회의 중에 폰에서 알람이 울렸는데 알람 제목이 ''퇴근하자!!''였습니다. 다 같이 웃었어요.', 'HUMOR', '["아재개그", "유머"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41272 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, '오늘 카페에서 있었던 일', '카페에서 아이스 아메리카노를 주문했는데 핫으로 나왔어요. 항의하려니까 제 앞 손님이 핫을 시켰는데 아이스가 나온 거였음 ㅋㅋㅋ 바뀐 거였다', 'HUMOR', '["웃김", "카페"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37727 MINUTE)),
  (2, '우리 팀 신입의 전설적인 실수', '신입이 git push --force를 main 브랜치에 했습니다. 팀 전체가 멘붕... 그래도 당일 복구했어요. 이후 branch protection이 생겼습니다.', 'HUMOR', '["웃김", "개발"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12742 MINUTE)),
  (3, '택배 기사님과의 대화', '택배 기사님이 문 앞에 놓고 가시면서 사진을 찍어주셨는데 우리 집 고양이가 택배 위에 앉아있는 사진이었어요 ㅋㅋ', 'HUMOR', '["택배", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25164 MINUTE)),
  (4, '어머니의 카톡 오타', '어머니가 카톡으로 ''밥 먹었니'' 대신 ''밤 먹었니'' 라고 보내셨는데, 아버지가 옆에서 ''밤이면 밤마다'' 하셔서 어머니한테 혼남 ㅋㅋ', 'HUMOR', '["부모님", "카톡"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32399 MINUTE)),
  (5, '회사에서 방귀 참다가 생긴 일', '회의 중에 배에서 꼬르륵 소리가 나서 기침으로 위장했는데, 팀장님이 ''감기 걸렸어? 오늘 일찍 퇴근해'' 라고 하셔서 일찍 퇴근했습니다. 럭키!', 'HUMOR', '["직장", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26191 MINUTE)),
  (6, '소개팅 역대급 썰', '소개팅에서 상대방이 제 회사 동기였습니다. 서로 당황해서 모르는 척 했는데 다음날 회사에서 마주쳐서 더 어색... 지금은 잘 사귀고 있어요 ㅎ', 'HUMOR', '["소개팅", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15989 MINUTE)),
  (7, '자취생의 냉장고 발굴기', '냉장고 안쪽에서 작년에 넣어둔 반찬통을 발견했는데 뚜껑을 열자마자 후회했습니다. 그냥 통째로 버렸어요...', 'HUMOR', '["자취", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9671 MINUTE)),
  (8, '코드 리뷰에서 발견한 주석', '코드 리뷰하다가 주석에 // TODO: 이거 왜 동작하는지 모름 을 발견했습니다. 작성자는 이미 퇴사한 사람이었어요.', 'HUMOR', '["코드리뷰", "개발"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42995 MINUTE)),
  (9, '오늘의 웃긴 배달 리뷰', '배달 리뷰에 ''맛있어서 화가 납니다. 다이어트 중이었거든요.'' 라고 써있어서 웃었습니다.', 'HUMOR', '["배달", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 363 MINUTE)),
  (10, '강아지가 택배 상자를 열었다', '택배가 와서 현관에 두었는데 우리 강아지가 상자를 다 찢어놓았어요. 안에 강아지 간식이 들어있었는데 이미 반은 먹은 상태...', 'HUMOR', '["반려동물", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6985 MINUTE)),
  (1, '회식에서 생긴 해프닝', '회식 2차에서 노래방 가서 부장님이 아이돌 춤을 추기 시작하셨는데 의외로 잘하셔서 다들 충격받음. 숨겨진 재능이었다.', 'HUMOR', '["회식", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27862 MINUTE)),
