  (6, '회사 엘리베이터 사건', '회식 2차에서 노래방 가서 부장님이 아이돌 춤을 추기 시작하셨는데 의외로 잘하셔서 다들 충격받음. 숨겨진 재능이었다.', 'HUMOR', '["소개팅", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16986 MINUTE)),
  (7, '배달 오배송 해프닝', '면접에서 자기소개 해달라는데 긴장해서 ''안녕하세요 저는 28살...'' 하다가 나이를 까먹었습니다.', 'HUMOR', '["자취", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16203 MINUTE)),
  (8, '새 후배의 귀여운 실수', '할머니께서 키오스크로 주문하시는데 화면을 누르면서 ''여보세요?'' 하셨어요. 할머니 귀여우셔...', 'HUMOR', '["코드리뷰", "개발"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41789 MINUTE)),
  (9, '운전면허 시험 썰', '중고나라에서 에어팟 팔려고 올렸더니 ''삼만원에 안 되냐''고 해서 안 된다고 했더니 ''그럼 이만원은?''이라는 답장이 왔습니다.', 'HUMOR', '["배달", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18173 MINUTE)),
  (10, '체육대회 레전드', '팀장님한테 보내야 할 카톡을 여자친구한테 보냈는데 ''네 알겠습니다 팀장님'' 이라고... 여친이 ''팀장님?ㅋㅋ'' 하고 넘어가줬어요.', 'HUMOR', '["반려동물", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 34163 MINUTE)),
  (1, '동물원에서 있었던 일', '새벽 3시에 치킨 시키고 후회하면서 먹었는데 맛있어서 다시 후회가 사라졌습니다.', 'HUMOR', '["회식", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31758 MINUTE)),
  (2, '오늘의 아재개그', '고양이가 제 화분을 다 엎어놓고 제 베개 위에서 자고 있었어요. 눈이 마주쳤는데 하품을 하더라고요.', 'HUMOR', '["면접", "긴장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41074 MINUTE)),
  (3, '카페 알바 손님 레전드', '술자리에서 선배가 ''나 원래 주량이 소주 3병이야''라고 했는데 소주 1병에 뻗었습니다.', 'HUMOR', '["어르신", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15679 MINUTE)),
  (4, '자취방 벌레 퇴치 대작전', '지하철에서 할아버지 두 분이 와이파이 비밀번호에 대해 열띤 토론을 하고 계셨어요. 결국 손자에게 전화하심.', 'HUMOR', '["중고거래", "레전드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17996 MINUTE)),
  (5, '친구의 어이없는 실수', '배달 리뷰에 ''짜장면에서 머리카락이 나왔는데 제 머리카락이었습니다. 죄송합니다.'' 별 다섯 개.', 'HUMOR', '["오타", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28827 MINUTE)),
  (6, '부장님의 반전 매력', '회사 단톡방에 여친한테 보낼 하트를 잘못 보냈습니다. 팀장님이 하트로 답해주셨어요.', 'HUMOR', '["새벽", "배달"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5077 MINUTE)),
  (7, '음식 배달 사고', '아버지한테 스마트폰 가르쳐드렸는데 유튜브에서 ''숏츠''를 발견하시고 3시간째 보고 계세요. 제가 만든 괴물...', 'HUMOR', '["고양이", "웃김"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18725 MINUTE)),
  (8, '단톡방 폭탄 발언', '편의점 알바할 때 손님이 ''이거 얼마예요?'' 하길래 바코드 찍었더니 ''가격이 0원입니다'' 나왔어요. 시스템 오류였는데 손님 눈이 반짝반짝.', 'HUMOR', '["술자리", "썰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15367 MINUTE)),
  (9, '동기의 황당한 변명', '엘리베이터에 나 혼자인 줄 알고 방귀를 뀌었는데 문이 열리면서 사람이 쏟아져 들어왔습니다. 그날 계단으로 다녔어요.', 'HUMOR', '["지하철", "목격"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17807 MINUTE)),
  (10, '오늘도 웃긴 하루', '회의 중에 폰에서 알람이 울렸는데 알람 제목이 ''퇴근하자!!''였습니다. 다 같이 웃었어요.', 'HUMOR', '["배달", "레전드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22010 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, '알뜰폰 요금제 비교 정리', '알뜰폰 요금제를 비교 분석해봤습니다. 월 1만원대로 데이터 5GB, 통화 무제한 쓸 수 있는 요금제가 있더라고요. 3대 통신사 대비 절반 이하 가격입니다.', 'INFORMATION', '["알뜰폰", "요금제"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20952 MINUTE)),
  (2, '2024 연말정산 꿀팁 모음', '연말정산 시즌이 다가오고 있어서 미리 준비하면 좋은 팁들 정리했습니다. 소득공제, 세액공제 항목별로 놓치기 쉬운 것들 모아봤어요.', 'INFORMATION', '["연말정산", "꿀팁"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35399 MINUTE)),
  (3, '무료 온라인 강의 사이트 추천', 'Coursera, edX, KOCW 등 무료로 들을 수 있는 양질의 강의 사이트를 정리했습니다. 프로그래밍, 데이터 사이언스, 경영학까지 다양합니다.', 'INFORMATION', '["온라인강의", "무료"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5280 MINUTE)),
  (4, '자취생 필수 앱 모음', '자취생활 3년 하면서 진짜 쓸모 있었던 앱들만 모아봤습니다. 가계부, 배달, 청소, 요리 레시피 등 카테고리별로 정리했어요.', 'INFORMATION', '["자취", "앱"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9068 MINUTE)),
  (5, '신용점수 올리는 방법', '신용점수가 낮아서 고민이신 분들, 제가 700점대에서 900점대로 올린 방법 공유합니다. 핵심은 꾸준한 소액 결제와 자동이체 설정이에요.', 'INFORMATION', '["신용점수", "재테크"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9884 MINUTE)),
  (6, '알바 구할 때 주의사항', '알바 구할 때 사기 피하는 방법과 근로계약서 필수 확인 항목을 정리했습니다. 최저시급, 4대보험, 주휴수당 등 꼭 체크하세요.', 'INFORMATION', '["알바", "주의사항"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15155 MINUTE)),
  (7, '전세 계약 시 체크리스트', '전세 계약 전에 반드시 확인해야 할 사항들을 체크리스트로 만들었습니다. 등기부등본, 확정일자, 전입신고 순서 등 놓치면 큰일 나는 것들이에요.', 'INFORMATION', '["전세", "체크리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25102 MINUTE)),
  (8, '건강보험료 줄이는 법', '건강보험료 절약 방법을 정리했습니다. 피부양자 등록, 소득 신고 시기, 임의계속가입 등 실질적으로 도움 되는 정보들입니다.', 'INFORMATION', '["건강보험", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10014 MINUTE)),
  (9, '서울 무료 문화 행사 정리', '이번 달 서울에서 무료로 즐길 수 있는 문화 행사와 전시를 모아봤습니다. 국립현대미술관, 서울시립미술관 무료 전시 포함이에요.', 'INFORMATION', '["문화행사", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14021 MINUTE)),
  (10, '노트북 구매 가이드', '2024년 기준 가성비 노트북 구매 가이드입니다. 용도별(개발, 사무, 디자인, 게임)로 추천 모델을 정리했습니다.', 'INFORMATION', '["노트북", "구매가이드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4209 MINUTE)),
  (1, '교통비 절약 팁', '교통비를 줄이는 다양한 방법을 소개합니다. 환승 할인, 정기 이용권, 기후동행카드, 자전거 활용까지 종합적으로 정리했어요.', 'INFORMATION', '["교통비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27188 MINUTE)),
  (2, '이직할 때 필요한 서류', '이직할 때 필요한 서류와 절차를 타임라인별로 정리했습니다. 퇴직금 정산, 4대보험, 원천징수영수증 등 빠뜨리기 쉬운 것들이 많습니다.', 'INFORMATION', '["이직", "서류"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26712 MINUTE)),
  (3, '1인 가구 식비 절약법', '1인 가구 기준 월 식비 30만원으로 건강하게 먹는 방법 공유합니다. 장보기 팁, 식단 구성, 밀프렙 방법 등을 정리했어요.', 'INFORMATION', '["식비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21684 MINUTE)),
  (4, '공공 와이파이 보안 주의', '공공 와이파이 사용할 때 개인정보 유출 위험이 있습니다. VPN 사용, 자동 연결 해제, HTTPS 확인 등 보안 수칙을 알려드립니다.', 'INFORMATION', '["보안", "와이파이"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35560 MINUTE)),
  (5, '중고차 구매 체크리스트', '중고차를 살 때 꼭 확인해야 할 것들을 정리했습니다. 사고 이력 조회, 침수 확인, 시승 체크포인트 등 실전 경험 기반으로 작성했어요.', 'INFORMATION', '["중고차", "구매"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30534 MINUTE)),
  (6, '전기세 줄이는 방법', '여름철 전기세 폭탄 피하는 방법 공유합니다. 에어컨 효율적 사용법, 대기전력 차단, 가전제품 에너지 등급 확인까지 정리했습니다.', 'INFORMATION', '["전기세", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27248 MINUTE)),
  (7, '무료 PDF 편집 사이트', 'PDF 편집, 병합, 변환을 무료로 할 수 있는 사이트와 프로그램을 모아봤습니다. SmallPDF, iLovePDF 등 비교 분석했어요.', 'INFORMATION', '["PDF", "무료"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4080 MINUTE)),
  (8, '프로그래밍 학습 로드맵', '비전공자를 위한 프로그래밍 학습 로드맵을 만들어봤습니다. HTML/CSS부터 시작해서 JavaScript, Python까지 단계별로 정리했어요.', 'INFORMATION', '["프로그래밍", "학습"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13555 MINUTE)),
  (9, '서울 도서관 추천 리스트', '서울 시내 조용하고 쾌적한 도서관 10곳을 추천합니다. 위치, 운영시간, 좌석 수, 특징별로 정리했어요.', 'INFORMATION', '["도서관", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27534 MINUTE)),
  (10, '통신비 줄이는 방법 총정리', '통신비를 월 2만원 이하로 줄이는 방법을 종합 정리했습니다. 알뜰폰 전환, 결합 할인, 멤버십 활용까지 총정리.', 'INFORMATION', '["통신비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25524 MINUTE)),
  (1, '연차 사용 팁 모음', '연차를 효율적으로 사용하는 방법과 법적으로 보장되는 휴가 일수, 연차 촉진 제도 등을 정리했습니다.', 'INFORMATION', '["연차", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38278 MINUTE)),
  (2, '유용한 크롬 확장프로그램', '개발자, 학생, 직장인에게 유용한 크롬 확장프로그램 20개를 카테고리별로 정리했습니다.', 'INFORMATION', '["크롬", "확장프로그램"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1280 MINUTE)),
  (3, '이사할 때 체크리스트', '이사할 때 빠뜨리기 쉬운 것들 체크리스트로 만들었습니다. 1개월 전, 2주 전, 당일, 이사 후 해야 할 일 타임라인 포함.', 'INFORMATION', '["이사", "체크리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37728 MINUTE)),
  (4, '비상금 마련 방법', '비상금 100만원을 3개월 만에 모은 방법을 공유합니다. 라테 팩터 줄이기, 자동 이체, 앱 활용 등 실전 팁이에요.', 'INFORMATION', '["비상금", "저축"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 24928 MINUTE)),
  (5, '개발자를 위한 무료 툴', '개발자에게 유용한 무료 도구들을 정리했습니다. IDE, 디자인, 프로젝트 관리, 모니터링 등 카테고리별 추천.', 'INFORMATION', '["개발자", "도구"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31259 MINUTE)),
  (6, '건강 검진 항목 가이드', '알뜰폰 요금제를 비교 분석해봤습니다. 월 1만원대로 데이터 5GB, 통화 무제한 쓸 수 있는 요금제가 있더라고요. 3대 통신사 대비 절반 이하 가격입니다.', 'INFORMATION', '["건강검진", "가이드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 386 MINUTE)),
  (7, '자동차 보험 비교', '연말정산 시즌이 다가오고 있어서 미리 준비하면 좋은 팁들 정리했습니다. 소득공제, 세액공제 항목별로 놓치기 쉬운 것들 모아봤어요.', 'INFORMATION', '["자동차보험", "비교"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23052 MINUTE)),
  (8, '알뜰 여행 팁 모음', 'Coursera, edX, KOCW 등 무료로 들을 수 있는 양질의 강의 사이트를 정리했습니다. 프로그래밍, 데이터 사이언스, 경영학까지 다양합니다.', 'INFORMATION', '["여행", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19569 MINUTE)),
  (9, '인테리어 저렴하게 하는 법', '자취생활 3년 하면서 진짜 쓸모 있었던 앱들만 모아봤습니다. 가계부, 배달, 청소, 요리 레시피 등 카테고리별로 정리했어요.', 'INFORMATION', '["인테리어", "저렴"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25558 MINUTE)),
  (10, '세금 신고 간단 정리', '신용점수가 낮아서 고민이신 분들, 제가 700점대에서 900점대로 올린 방법 공유합니다. 핵심은 꾸준한 소액 결제와 자동이체 설정이에요.', 'INFORMATION', '["세금", "정보"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27460 MINUTE)),
  (1, '면접 준비 가이드', '알바 구할 때 사기 피하는 방법과 근로계약서 필수 확인 항목을 정리했습니다. 최저시급, 4대보험, 주휴수당 등 꼭 체크하세요.', 'INFORMATION', '["알뜰폰", "요금제"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35272 MINUTE)),
  (2, '홈트레이닝 장비 추천', '전세 계약 전에 반드시 확인해야 할 사항들을 체크리스트로 만들었습니다. 등기부등본, 확정일자, 전입신고 순서 등 놓치면 큰일 나는 것들이에요.', 'INFORMATION', '["연말정산", "꿀팁"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35791 MINUTE)),
  (3, '넷플릭스 숨겨진 코드 모음', '건강보험료 절약 방법을 정리했습니다. 피부양자 등록, 소득 신고 시기, 임의계속가입 등 실질적으로 도움 되는 정보들입니다.', 'INFORMATION', '["온라인강의", "무료"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39534 MINUTE)),
  (4, '무료 이미지 사이트 추천', '이번 달 서울에서 무료로 즐길 수 있는 문화 행사와 전시를 모아봤습니다. 국립현대미술관, 서울시립미술관 무료 전시 포함이에요.', 'INFORMATION', '["자취", "앱"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14453 MINUTE)),
  (5, '맥북 생산성 앱 추천', '2024년 기준 가성비 노트북 구매 가이드입니다. 용도별(개발, 사무, 디자인, 게임)로 추천 모델을 정리했습니다.', 'INFORMATION', '["신용점수", "재테크"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31996 MINUTE)),
  (6, '카드 혜택 비교 정리', '교통비를 줄이는 다양한 방법을 소개합니다. 환승 할인, 정기 이용권, 기후동행카드, 자전거 활용까지 종합적으로 정리했어요.', 'INFORMATION', '["알바", "주의사항"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14380 MINUTE)),
  (7, '수면의 질 올리는 방법', '이직할 때 필요한 서류와 절차를 타임라인별로 정리했습니다. 퇴직금 정산, 4대보험, 원천징수영수증 등 빠뜨리기 쉬운 것들이 많습니다.', 'INFORMATION', '["전세", "체크리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17887 MINUTE)),
  (8, '청약 준비 가이드', '1인 가구 기준 월 식비 30만원으로 건강하게 먹는 방법 공유합니다. 장보기 팁, 식단 구성, 밀프렙 방법 등을 정리했어요.', 'INFORMATION', '["건강보험", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28562 MINUTE)),
  (9, '무료 디자인 툴 모음', '공공 와이파이 사용할 때 개인정보 유출 위험이 있습니다. VPN 사용, 자동 연결 해제, HTTPS 확인 등 보안 수칙을 알려드립니다.', 'INFORMATION', '["문화행사", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31827 MINUTE)),
  (10, '요리 입문 필수템 추천', '중고차를 살 때 꼭 확인해야 할 것들을 정리했습니다. 사고 이력 조회, 침수 확인, 시승 체크포인트 등 실전 경험 기반으로 작성했어요.', 'INFORMATION', '["노트북", "구매가이드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1902 MINUTE)),
  (1, '재택근무 생산성 높이는 법', '여름철 전기세 폭탄 피하는 방법 공유합니다. 에어컨 효율적 사용법, 대기전력 차단, 가전제품 에너지 등급 확인까지 정리했습니다.', 'INFORMATION', '["교통비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25484 MINUTE)),
  (2, '독서 습관 만드는 방법', 'PDF 편집, 병합, 변환을 무료로 할 수 있는 사이트와 프로그램을 모아봤습니다. SmallPDF, iLovePDF 등 비교 분석했어요.', 'INFORMATION', '["이직", "서류"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22028 MINUTE)),
  (3, '유튜브 프리미엄 우회 꿀팁', '비전공자를 위한 프로그래밍 학습 로드맵을 만들어봤습니다. HTML/CSS부터 시작해서 JavaScript, Python까지 단계별로 정리했어요.', 'INFORMATION', '["식비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26497 MINUTE)),
  (4, '사회초년생 보험 가이드', '서울 시내 조용하고 쾌적한 도서관 10곳을 추천합니다. 위치, 운영시간, 좌석 수, 특징별로 정리했어요.', 'INFORMATION', '["보안", "와이파이"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10816 MINUTE)),
  (5, '무료 음악 스트리밍 서비스', '통신비를 월 2만원 이하로 줄이는 방법을 종합 정리했습니다. 알뜰폰 전환, 결합 할인, 멤버십 활용까지 총정리.', 'INFORMATION', '["중고차", "구매"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30630 MINUTE)),
  (6, '서울 주차장 할인 정보', '연차를 효율적으로 사용하는 방법과 법적으로 보장되는 휴가 일수, 연차 촉진 제도 등을 정리했습니다.', 'INFORMATION', '["전기세", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8364 MINUTE)),
  (7, '건강한 식단 구성법', '개발자, 학생, 직장인에게 유용한 크롬 확장프로그램 20개를 카테고리별로 정리했습니다.', 'INFORMATION', '["PDF", "무료"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40780 MINUTE)),
  (8, '이사 비용 절약 팁', '이사할 때 빠뜨리기 쉬운 것들 체크리스트로 만들었습니다. 1개월 전, 2주 전, 당일, 이사 후 해야 할 일 타임라인 포함.', 'INFORMATION', '["프로그래밍", "학습"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35004 MINUTE)),
  (9, '프리랜서 세금 가이드', '비상금 100만원을 3개월 만에 모은 방법을 공유합니다. 라테 팩터 줄이기, 자동 이체, 앱 활용 등 실전 팁이에요.', 'INFORMATION', '["도서관", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1767 MINUTE)),
  (10, '에너지 절약 생활 팁', '개발자에게 유용한 무료 도구들을 정리했습니다. IDE, 디자인, 프로젝트 관리, 모니터링 등 카테고리별 추천.', 'INFORMATION', '["통신비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25822 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, '알뜰폰 요금제 비교 정리', '알뜰폰 요금제를 비교 분석해봤습니다. 월 1만원대로 데이터 5GB, 통화 무제한 쓸 수 있는 요금제가 있더라고요. 3대 통신사 대비 절반 이하 가격입니다.', 'INFORMATION', '["연차", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38790 MINUTE)),
  (2, '2024 연말정산 꿀팁 모음', '연말정산 시즌이 다가오고 있어서 미리 준비하면 좋은 팁들 정리했습니다. 소득공제, 세액공제 항목별로 놓치기 쉬운 것들 모아봤어요.', 'INFORMATION', '["크롬", "확장프로그램"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36987 MINUTE)),
  (3, '무료 온라인 강의 사이트 추천', 'Coursera, edX, KOCW 등 무료로 들을 수 있는 양질의 강의 사이트를 정리했습니다. 프로그래밍, 데이터 사이언스, 경영학까지 다양합니다.', 'INFORMATION', '["이사", "체크리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1776 MINUTE)),
  (4, '자취생 필수 앱 모음', '자취생활 3년 하면서 진짜 쓸모 있었던 앱들만 모아봤습니다. 가계부, 배달, 청소, 요리 레시피 등 카테고리별로 정리했어요.', 'INFORMATION', '["비상금", "저축"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5501 MINUTE)),
  (5, '신용점수 올리는 방법', '신용점수가 낮아서 고민이신 분들, 제가 700점대에서 900점대로 올린 방법 공유합니다. 핵심은 꾸준한 소액 결제와 자동이체 설정이에요.', 'INFORMATION', '["개발자", "도구"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42123 MINUTE)),
  (6, '알바 구할 때 주의사항', '알바 구할 때 사기 피하는 방법과 근로계약서 필수 확인 항목을 정리했습니다. 최저시급, 4대보험, 주휴수당 등 꼭 체크하세요.', 'INFORMATION', '["건강검진", "가이드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28089 MINUTE)),
  (7, '전세 계약 시 체크리스트', '전세 계약 전에 반드시 확인해야 할 사항들을 체크리스트로 만들었습니다. 등기부등본, 확정일자, 전입신고 순서 등 놓치면 큰일 나는 것들이에요.', 'INFORMATION', '["자동차보험", "비교"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8893 MINUTE)),
  (8, '건강보험료 줄이는 법', '건강보험료 절약 방법을 정리했습니다. 피부양자 등록, 소득 신고 시기, 임의계속가입 등 실질적으로 도움 되는 정보들입니다.', 'INFORMATION', '["여행", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30257 MINUTE)),
  (9, '서울 무료 문화 행사 정리', '이번 달 서울에서 무료로 즐길 수 있는 문화 행사와 전시를 모아봤습니다. 국립현대미술관, 서울시립미술관 무료 전시 포함이에요.', 'INFORMATION', '["인테리어", "저렴"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 11909 MINUTE)),
