  (6, '전기세 줄이는 방법', '여름철 전기세 폭탄 피하는 방법 공유합니다. 에어컨 효율적 사용법, 대기전력 차단, 가전제품 에너지 등급 확인까지 정리했습니다.', 'INFORMATION', '["전기세", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31952 MINUTE)),
  (7, '무료 PDF 편집 사이트', 'PDF 편집, 병합, 변환을 무료로 할 수 있는 사이트와 프로그램을 모아봤습니다. SmallPDF, iLovePDF 등 비교 분석했어요.', 'INFORMATION', '["PDF", "무료"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13901 MINUTE)),
  (8, '프로그래밍 학습 로드맵', '비전공자를 위한 프로그래밍 학습 로드맵을 만들어봤습니다. HTML/CSS부터 시작해서 JavaScript, Python까지 단계별로 정리했어요.', 'INFORMATION', '["프로그래밍", "학습"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23253 MINUTE)),
  (9, '서울 도서관 추천 리스트', '서울 시내 조용하고 쾌적한 도서관 10곳을 추천합니다. 위치, 운영시간, 좌석 수, 특징별로 정리했어요.', 'INFORMATION', '["도서관", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16931 MINUTE)),
  (10, '통신비 줄이는 방법 총정리', '통신비를 월 2만원 이하로 줄이는 방법을 종합 정리했습니다. 알뜰폰 전환, 결합 할인, 멤버십 활용까지 총정리.', 'INFORMATION', '["통신비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22304 MINUTE)),
  (1, '연차 사용 팁 모음', '연차를 효율적으로 사용하는 방법과 법적으로 보장되는 휴가 일수, 연차 촉진 제도 등을 정리했습니다.', 'INFORMATION', '["연차", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18327 MINUTE)),
  (2, '유용한 크롬 확장프로그램', '개발자, 학생, 직장인에게 유용한 크롬 확장프로그램 20개를 카테고리별로 정리했습니다.', 'INFORMATION', '["크롬", "확장프로그램"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39069 MINUTE)),
  (3, '이사할 때 체크리스트', '이사할 때 빠뜨리기 쉬운 것들 체크리스트로 만들었습니다. 1개월 전, 2주 전, 당일, 이사 후 해야 할 일 타임라인 포함.', 'INFORMATION', '["이사", "체크리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18105 MINUTE)),
  (4, '비상금 마련 방법', '비상금 100만원을 3개월 만에 모은 방법을 공유합니다. 라테 팩터 줄이기, 자동 이체, 앱 활용 등 실전 팁이에요.', 'INFORMATION', '["비상금", "저축"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36424 MINUTE)),
  (5, '개발자를 위한 무료 툴', '개발자에게 유용한 무료 도구들을 정리했습니다. IDE, 디자인, 프로젝트 관리, 모니터링 등 카테고리별 추천.', 'INFORMATION', '["개발자", "도구"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 665 MINUTE)),
  (6, '건강 검진 항목 가이드', '알뜰폰 요금제를 비교 분석해봤습니다. 월 1만원대로 데이터 5GB, 통화 무제한 쓸 수 있는 요금제가 있더라고요. 3대 통신사 대비 절반 이하 가격입니다.', 'INFORMATION', '["건강검진", "가이드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33857 MINUTE)),
  (7, '자동차 보험 비교', '연말정산 시즌이 다가오고 있어서 미리 준비하면 좋은 팁들 정리했습니다. 소득공제, 세액공제 항목별로 놓치기 쉬운 것들 모아봤어요.', 'INFORMATION', '["자동차보험", "비교"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12521 MINUTE)),
  (8, '알뜰 여행 팁 모음', 'Coursera, edX, KOCW 등 무료로 들을 수 있는 양질의 강의 사이트를 정리했습니다. 프로그래밍, 데이터 사이언스, 경영학까지 다양합니다.', 'INFORMATION', '["여행", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5610 MINUTE)),
  (9, '인테리어 저렴하게 하는 법', '자취생활 3년 하면서 진짜 쓸모 있었던 앱들만 모아봤습니다. 가계부, 배달, 청소, 요리 레시피 등 카테고리별로 정리했어요.', 'INFORMATION', '["인테리어", "저렴"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15817 MINUTE)),
  (10, '세금 신고 간단 정리', '신용점수가 낮아서 고민이신 분들, 제가 700점대에서 900점대로 올린 방법 공유합니다. 핵심은 꾸준한 소액 결제와 자동이체 설정이에요.', 'INFORMATION', '["세금", "정보"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26635 MINUTE)),
  (1, '면접 준비 가이드', '알바 구할 때 사기 피하는 방법과 근로계약서 필수 확인 항목을 정리했습니다. 최저시급, 4대보험, 주휴수당 등 꼭 체크하세요.', 'INFORMATION', '["알뜰폰", "요금제"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32019 MINUTE)),
  (2, '홈트레이닝 장비 추천', '전세 계약 전에 반드시 확인해야 할 사항들을 체크리스트로 만들었습니다. 등기부등본, 확정일자, 전입신고 순서 등 놓치면 큰일 나는 것들이에요.', 'INFORMATION', '["연말정산", "꿀팁"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36384 MINUTE)),
  (3, '넷플릭스 숨겨진 코드 모음', '건강보험료 절약 방법을 정리했습니다. 피부양자 등록, 소득 신고 시기, 임의계속가입 등 실질적으로 도움 되는 정보들입니다.', 'INFORMATION', '["온라인강의", "무료"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15749 MINUTE)),
  (4, '무료 이미지 사이트 추천', '이번 달 서울에서 무료로 즐길 수 있는 문화 행사와 전시를 모아봤습니다. 국립현대미술관, 서울시립미술관 무료 전시 포함이에요.', 'INFORMATION', '["자취", "앱"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31201 MINUTE)),
  (5, '맥북 생산성 앱 추천', '2024년 기준 가성비 노트북 구매 가이드입니다. 용도별(개발, 사무, 디자인, 게임)로 추천 모델을 정리했습니다.', 'INFORMATION', '["신용점수", "재테크"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42329 MINUTE)),
  (6, '카드 혜택 비교 정리', '교통비를 줄이는 다양한 방법을 소개합니다. 환승 할인, 정기 이용권, 기후동행카드, 자전거 활용까지 종합적으로 정리했어요.', 'INFORMATION', '["알바", "주의사항"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32166 MINUTE)),
  (7, '수면의 질 올리는 방법', '이직할 때 필요한 서류와 절차를 타임라인별로 정리했습니다. 퇴직금 정산, 4대보험, 원천징수영수증 등 빠뜨리기 쉬운 것들이 많습니다.', 'INFORMATION', '["전세", "체크리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29371 MINUTE)),
  (8, '청약 준비 가이드', '1인 가구 기준 월 식비 30만원으로 건강하게 먹는 방법 공유합니다. 장보기 팁, 식단 구성, 밀프렙 방법 등을 정리했어요.', 'INFORMATION', '["건강보험", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1130 MINUTE)),
  (9, '무료 디자인 툴 모음', '공공 와이파이 사용할 때 개인정보 유출 위험이 있습니다. VPN 사용, 자동 연결 해제, HTTPS 확인 등 보안 수칙을 알려드립니다.', 'INFORMATION', '["문화행사", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6098 MINUTE)),
  (10, '요리 입문 필수템 추천', '중고차를 살 때 꼭 확인해야 할 것들을 정리했습니다. 사고 이력 조회, 침수 확인, 시승 체크포인트 등 실전 경험 기반으로 작성했어요.', 'INFORMATION', '["노트북", "구매가이드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19283 MINUTE)),
  (1, '재택근무 생산성 높이는 법', '여름철 전기세 폭탄 피하는 방법 공유합니다. 에어컨 효율적 사용법, 대기전력 차단, 가전제품 에너지 등급 확인까지 정리했습니다.', 'INFORMATION', '["교통비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14522 MINUTE)),
  (2, '독서 습관 만드는 방법', 'PDF 편집, 병합, 변환을 무료로 할 수 있는 사이트와 프로그램을 모아봤습니다. SmallPDF, iLovePDF 등 비교 분석했어요.', 'INFORMATION', '["이직", "서류"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26502 MINUTE)),
  (3, '유튜브 프리미엄 우회 꿀팁', '비전공자를 위한 프로그래밍 학습 로드맵을 만들어봤습니다. HTML/CSS부터 시작해서 JavaScript, Python까지 단계별로 정리했어요.', 'INFORMATION', '["식비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15945 MINUTE)),
  (4, '사회초년생 보험 가이드', '서울 시내 조용하고 쾌적한 도서관 10곳을 추천합니다. 위치, 운영시간, 좌석 수, 특징별로 정리했어요.', 'INFORMATION', '["보안", "와이파이"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20067 MINUTE)),
  (5, '무료 음악 스트리밍 서비스', '통신비를 월 2만원 이하로 줄이는 방법을 종합 정리했습니다. 알뜰폰 전환, 결합 할인, 멤버십 활용까지 총정리.', 'INFORMATION', '["중고차", "구매"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38112 MINUTE)),
  (6, '서울 주차장 할인 정보', '연차를 효율적으로 사용하는 방법과 법적으로 보장되는 휴가 일수, 연차 촉진 제도 등을 정리했습니다.', 'INFORMATION', '["전기세", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 24184 MINUTE)),
  (7, '건강한 식단 구성법', '개발자, 학생, 직장인에게 유용한 크롬 확장프로그램 20개를 카테고리별로 정리했습니다.', 'INFORMATION', '["PDF", "무료"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31015 MINUTE)),
  (8, '이사 비용 절약 팁', '이사할 때 빠뜨리기 쉬운 것들 체크리스트로 만들었습니다. 1개월 전, 2주 전, 당일, 이사 후 해야 할 일 타임라인 포함.', 'INFORMATION', '["프로그래밍", "학습"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36272 MINUTE)),
  (9, '프리랜서 세금 가이드', '비상금 100만원을 3개월 만에 모은 방법을 공유합니다. 라테 팩터 줄이기, 자동 이체, 앱 활용 등 실전 팁이에요.', 'INFORMATION', '["도서관", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 34794 MINUTE)),
  (10, '에너지 절약 생활 팁', '개발자에게 유용한 무료 도구들을 정리했습니다. IDE, 디자인, 프로젝트 관리, 모니터링 등 카테고리별 추천.', 'INFORMATION', '["통신비", "절약"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22528 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, 'Docker 컨테이너 네트워크 질문', 'Docker 컨테이너끼리 통신하려면 네트워크를 어떻게 구성해야 하나요? docker-compose로 여러 서비스를 띄우고 있는데 연결이 안 됩니다.', 'QUESTION', '["Docker", "네트워크"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27885 MINUTE)),
  (2, 'Kotlin coroutine 사용법 질문', 'Kotlin coroutine을 실무에서 사용하고 계신 분 있나요? structured concurrency 개념이 잘 이해가 안 되는데 설명해주실 수 있나요?', 'QUESTION', '["Kotlin", "coroutine"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36070 MINUTE)),
  (3, '맥북 에어 vs 프로 뭐가 나을까요', '개발 용도로 맥북을 사려는데 에어 M3랑 프로 M3 중에 뭐가 나을까요? Docker를 많이 사용합니다.', 'QUESTION', '["맥북", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21678 MINUTE)),
  (4, '서울 1인 가구 월세 얼마가 적당한가요', '서울에서 직장 다니는 사회초년생인데 월세 얼마 정도가 적당한가요? 지역은 2호선 라인 기준입니다.', 'QUESTION', '["월세", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23056 MINUTE)),
  (5, 'JPA N+1 문제 해결 방법', 'JPA에서 N+1 문제가 발생하는데 fetch join 말고 다른 해결 방법이 있을까요? BatchSize, EntityGraph 등 비교해주세요.', 'QUESTION', '["JPA", "N+1"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29736 MINUTE)),
  (6, '이어폰 추천 부탁드립니다', '출퇴근용 무선 이어폰 추천해주세요. 예산 15만원 이하, 노이즈캔슬링 있으면 좋겠습니다.', 'QUESTION', '["이어폰", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17754 MINUTE)),
  (7, 'Spring Security 설정 질문', 'Spring Security 6에서 SecurityFilterChain 설정하는데 자꾸 403이 나옵니다. CSRF 비활성화도 했는데 뭐가 문제일까요?', 'QUESTION', '["Spring", "Security"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20094 MINUTE)),
  (8, '전세 vs 월세 어떤 게 나을까요', '전세 대출 받아서 전세 사는 게 나을까요, 아니면 월세가 나을까요? 보증금 5천에 월세 70 vs 전세 2억 기준입니다.', 'QUESTION', '["전세", "월세"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16475 MINUTE)),
  (9, 'Redis 캐시 전략 질문', 'Redis를 캐시로 사용할 때 cache-aside vs write-through vs write-behind 각각 어떤 상황에서 써야 하나요?', 'QUESTION', '["Redis", "캐시"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15108 MINUTE)),
  (10, '헬스장 처음 가는데 뭐부터 하나요', '헬스장을 처음 가보려는데 뭐부터 하면 좋을까요? 운동 루틴이나 주의사항 알려주세요.', 'QUESTION', '["헬스", "입문"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7907 MINUTE)),
  (1, 'Git 브랜치 전략 어떻게 하시나요', 'Git 브랜치 전략으로 Git Flow vs GitHub Flow vs Trunk-Based 중 뭐가 좋은가요? 팀 규모 5명입니다.', 'QUESTION', '["Git", "브랜치"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12621 MINUTE)),
  (2, '식세기 구매 고민 중입니다', '식기세척기 구매를 고민 중인데 빌트인 vs 프리스탠딩 장단점 알려주세요. 자취 원룸입니다.', 'QUESTION', '["식세기", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20679 MINUTE)),
  (3, 'Kafka consumer lag 해결 방법', 'Kafka consumer lag이 계속 쌓이고 있는데 파티션 수 늘리는 것 외에 다른 방법이 있을까요?', 'QUESTION', '["Kafka", "consumer"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7835 MINUTE)),
  (4, '첫 해외여행 준비물 질문', '처음 해외여행 가는데 준비물이 뭐가 필요한가요? 여권 발급은 했고 일본 3박 4일 예정입니다.', 'QUESTION', '["해외여행", "준비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35118 MINUTE)),
  (5, 'MySQL 인덱스 설계 질문', 'MySQL에서 복합 인덱스를 설계할 때 컬럼 순서를 어떻게 정해야 하나요? WHERE, ORDER BY, GROUP BY 조합별로 알려주세요.', 'QUESTION', '["MySQL", "인덱스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12133 MINUTE)),
  (6, '공기청정기 추천해주세요', '방 크기 10평 정도인데 공기청정기 추천해주세요. 미세먼지 심한 날 효과 있나요?', 'QUESTION', '["공기청정기", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12552 MINUTE)),
  (7, 'REST vs GraphQL 어떤 상황에서', 'REST API로 잘 쓰고 있는데 GraphQL로 전환할 이유가 있을까요? 프론트엔드 팀이 요청하는 중입니다.', 'QUESTION', '["REST", "GraphQL"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14180 MINUTE)),
  (8, '원룸 vs 투룸 뭐가 나을까요', '자취를 시작하려는데 원룸이 나을까요 투룸이 나을까요? 예산 월세 60만원 기준입니다.', 'QUESTION', '["원룸", "자취"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31732 MINUTE)),
  (9, 'Kubernetes pod 재시작 문제', 'Kubernetes에서 pod가 OOMKilled로 자꾸 재시작됩니다. 메모리 limit을 올리는 것 외에 방법이 있을까요?', 'QUESTION', '["Kubernetes", "OOM"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18120 MINUTE)),
  (10, '커피 머신 추천 부탁합니다', '집에서 쓸 커피 머신 추천해주세요. 캡슐 vs 반자동 vs 전자동 장단점 알려주시면 감사하겠습니다.', 'QUESTION', '["커피머신", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38639 MINUTE)),
  (1, 'AWS Lambda vs EC2 선택 기준', '서버리스(Lambda)와 EC2 중 어떤 상황에서 뭘 써야 하나요? 현재 트래픽이 불규칙한 API 서버를 운영 중입니다.', 'QUESTION', '["AWS", "Lambda"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 34382 MINUTE)),
  (2, '제습기 추천 부탁드립니다', '여름철 제습기 추천해주세요. 방 크기 8평 기준이고 예산은 30만원 이하입니다.', 'QUESTION', '["제습기", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39111 MINUTE)),
  (3, 'Spring Batch 성능 최적화 방법', 'Spring Batch로 천만 건 데이터를 처리하는데 속도가 너무 느립니다. chunk size, 병렬 처리 관련 최적화 방법 알려주세요.', 'QUESTION', '["SpringBatch", "성능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18546 MINUTE)),
  (4, '전기 자전거 추천해주세요', '출퇴근용 전기 자전거 추천해주세요. 편도 5km 정도이고 예산은 100만원 이하입니다.', 'QUESTION', '["전기자전거", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6588 MINUTE)),
  (5, 'OpenSearch 쿼리 최적화 질문', 'OpenSearch에서 multi_match 쿼리 성능이 느린데 최적화 방법이 있을까요? 인덱스 수천만 건입니다.', 'QUESTION', '["OpenSearch", "쿼리"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12721 MINUTE)),
  (6, '무선 키보드 추천 부탁합니다', 'Docker 컨테이너끼리 통신하려면 네트워크를 어떻게 구성해야 하나요? docker-compose로 여러 서비스를 띄우고 있는데 연결이 안 됩니다.', 'QUESTION', '["키보드", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19414 MINUTE)),
  (7, 'MSA 전환 시 주의사항', 'Kotlin coroutine을 실무에서 사용하고 계신 분 있나요? structured concurrency 개념이 잘 이해가 안 되는데 설명해주실 수 있나요?', 'QUESTION', '["MSA", "전환"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14908 MINUTE)),
  (8, '서울 근교 당일치기 여행지 추천', '개발 용도로 맥북을 사려는데 에어 M3랑 프로 M3 중에 뭐가 나을까요? Docker를 많이 사용합니다.', 'QUESTION', '["여행", "서울근교"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23650 MINUTE)),
  (9, 'IntelliJ 유용한 단축키', '서울에서 직장 다니는 사회초년생인데 월세 얼마 정도가 적당한가요? 지역은 2호선 라인 기준입니다.', 'QUESTION', '["IntelliJ", "단축키"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 11759 MINUTE)),
  (10, '블루투스 스피커 추천해주세요', 'JPA에서 N+1 문제가 발생하는데 fetch join 말고 다른 해결 방법이 있을까요? BatchSize, EntityGraph 등 비교해주세요.', 'QUESTION', '["스피커", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19809 MINUTE)),
  (1, 'WebFlux vs MVC 선택 기준', '출퇴근용 무선 이어폰 추천해주세요. 예산 15만원 이하, 노이즈캔슬링 있으면 좋겠습니다.', 'QUESTION', '["Docker", "네트워크"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 927 MINUTE)),
  (2, '자취 필수 가전 추천', 'Spring Security 6에서 SecurityFilterChain 설정하는데 자꾸 403이 나옵니다. CSRF 비활성화도 했는데 뭐가 문제일까요?', 'QUESTION', '["Kotlin", "coroutine"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35005 MINUTE)),
  (3, 'CI/CD 파이프라인 구성 질문', '전세 대출 받아서 전세 사는 게 나을까요, 아니면 월세가 나을까요? 보증금 5천에 월세 70 vs 전세 2억 기준입니다.', 'QUESTION', '["맥북", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8295 MINUTE)),
  (4, '노이즈캔슬링 이어폰 추천', 'Redis를 캐시로 사용할 때 cache-aside vs write-through vs write-behind 각각 어떤 상황에서 써야 하나요?', 'QUESTION', '["월세", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17977 MINUTE)),
  (5, 'JVM 메모리 튜닝 방법', '헬스장을 처음 가보려는데 뭐부터 하면 좋을까요? 운동 루틴이나 주의사항 알려주세요.', 'QUESTION', '["JPA", "N+1"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 2982 MINUTE)),
  (6, '맛있는 밀키트 추천해주세요', 'Git 브랜치 전략으로 Git Flow vs GitHub Flow vs Trunk-Based 중 뭐가 좋은가요? 팀 규모 5명입니다.', 'QUESTION', '["이어폰", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3573 MINUTE)),
  (7, 'Terraform vs CloudFormation', '식기세척기 구매를 고민 중인데 빌트인 vs 프리스탠딩 장단점 알려주세요. 자취 원룸입니다.', 'QUESTION', '["Spring", "Security"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36264 MINUTE)),
  (8, '인덕션 vs 가스레인지', 'Kafka consumer lag이 계속 쌓이고 있는데 파티션 수 늘리는 것 외에 다른 방법이 있을까요?', 'QUESTION', '["전세", "월세"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19145 MINUTE)),
  (9, 'gRPC 도입 경험 있으신가요', '처음 해외여행 가는데 준비물이 뭐가 필요한가요? 여권 발급은 했고 일본 3박 4일 예정입니다.', 'QUESTION', '["Redis", "캐시"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8275 MINUTE)),
