  (6, '무선 키보드 추천 부탁합니다', 'Docker 컨테이너끼리 통신하려면 네트워크를 어떻게 구성해야 하나요? docker-compose로 여러 서비스를 띄우고 있는데 연결이 안 됩니다.', 'QUESTION', '["이어폰", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10873 MINUTE)),
  (7, 'MSA 전환 시 주의사항', 'Kotlin coroutine을 실무에서 사용하고 계신 분 있나요? structured concurrency 개념이 잘 이해가 안 되는데 설명해주실 수 있나요?', 'QUESTION', '["Spring", "Security"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20159 MINUTE)),
  (8, '서울 근교 당일치기 여행지 추천', '개발 용도로 맥북을 사려는데 에어 M3랑 프로 M3 중에 뭐가 나을까요? Docker를 많이 사용합니다.', 'QUESTION', '["전세", "월세"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38996 MINUTE)),
  (9, 'IntelliJ 유용한 단축키', '서울에서 직장 다니는 사회초년생인데 월세 얼마 정도가 적당한가요? 지역은 2호선 라인 기준입니다.', 'QUESTION', '["Redis", "캐시"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37303 MINUTE)),
  (10, '블루투스 스피커 추천해주세요', 'JPA에서 N+1 문제가 발생하는데 fetch join 말고 다른 해결 방법이 있을까요? BatchSize, EntityGraph 등 비교해주세요.', 'QUESTION', '["헬스", "입문"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18914 MINUTE)),
  (1, 'WebFlux vs MVC 선택 기준', '출퇴근용 무선 이어폰 추천해주세요. 예산 15만원 이하, 노이즈캔슬링 있으면 좋겠습니다.', 'QUESTION', '["Git", "브랜치"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28780 MINUTE)),
  (2, '자취 필수 가전 추천', 'Spring Security 6에서 SecurityFilterChain 설정하는데 자꾸 403이 나옵니다. CSRF 비활성화도 했는데 뭐가 문제일까요?', 'QUESTION', '["식세기", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8149 MINUTE)),
  (3, 'CI/CD 파이프라인 구성 질문', '전세 대출 받아서 전세 사는 게 나을까요, 아니면 월세가 나을까요? 보증금 5천에 월세 70 vs 전세 2억 기준입니다.', 'QUESTION', '["Kafka", "consumer"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30716 MINUTE)),
  (4, '노이즈캔슬링 이어폰 추천', 'Redis를 캐시로 사용할 때 cache-aside vs write-through vs write-behind 각각 어떤 상황에서 써야 하나요?', 'QUESTION', '["해외여행", "준비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19928 MINUTE)),
  (5, 'JVM 메모리 튜닝 방법', '헬스장을 처음 가보려는데 뭐부터 하면 좋을까요? 운동 루틴이나 주의사항 알려주세요.', 'QUESTION', '["MySQL", "인덱스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26378 MINUTE)),
  (6, '맛있는 밀키트 추천해주세요', 'Git 브랜치 전략으로 Git Flow vs GitHub Flow vs Trunk-Based 중 뭐가 좋은가요? 팀 규모 5명입니다.', 'QUESTION', '["공기청정기", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17841 MINUTE)),
  (7, 'Terraform vs CloudFormation', '식기세척기 구매를 고민 중인데 빌트인 vs 프리스탠딩 장단점 알려주세요. 자취 원룸입니다.', 'QUESTION', '["REST", "GraphQL"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32798 MINUTE)),
  (8, '인덕션 vs 가스레인지', 'Kafka consumer lag이 계속 쌓이고 있는데 파티션 수 늘리는 것 외에 다른 방법이 있을까요?', 'QUESTION', '["원룸", "자취"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35388 MINUTE)),
  (9, 'gRPC 도입 경험 있으신가요', '처음 해외여행 가는데 준비물이 뭐가 필요한가요? 여권 발급은 했고 일본 3박 4일 예정입니다.', 'QUESTION', '["Kubernetes", "OOM"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32361 MINUTE)),
  (10, '로봇청소기 추천 부탁드립니다', 'MySQL에서 복합 인덱스를 설계할 때 컬럼 순서를 어떻게 정해야 하나요? WHERE, ORDER BY, GROUP BY 조합별로 알려주세요.', 'QUESTION', '["커피머신", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28688 MINUTE)),
  (1, '효율적인 코드 리뷰 방법', '방 크기 10평 정도인데 공기청정기 추천해주세요. 미세먼지 심한 날 효과 있나요?', 'QUESTION', '["AWS", "Lambda"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5271 MINUTE)),
  (2, '서울 맛집 추천해주세요', 'REST API로 잘 쓰고 있는데 GraphQL로 전환할 이유가 있을까요? 프론트엔드 팀이 요청하는 중입니다.', 'QUESTION', '["제습기", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39192 MINUTE)),
  (3, 'Gradle 빌드 속도 개선 방법', '자취를 시작하려는데 원룸이 나을까요 투룸이 나을까요? 예산 월세 60만원 기준입니다.', 'QUESTION', '["SpringBatch", "성능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 2612 MINUTE)),
  (4, '캠핑 입문 장비 추천', 'Kubernetes에서 pod가 OOMKilled로 자꾸 재시작됩니다. 메모리 limit을 올리는 것 외에 방법이 있을까요?', 'QUESTION', '["전기자전거", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28313 MINUTE)),
  (5, 'ElasticSearch 클러스터 설계', '집에서 쓸 커피 머신 추천해주세요. 캡슐 vs 반자동 vs 전자동 장단점 알려주시면 감사하겠습니다.', 'QUESTION', '["OpenSearch", "쿼리"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21123 MINUTE)),
  (6, '겨울 패딩 추천해주세요', '서버리스(Lambda)와 EC2 중 어떤 상황에서 뭘 써야 하나요? 현재 트래픽이 불규칙한 API 서버를 운영 중입니다.', 'QUESTION', '["키보드", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39564 MINUTE)),
  (7, 'Spring Cloud Gateway 질문', '여름철 제습기 추천해주세요. 방 크기 8평 기준이고 예산은 30만원 이하입니다.', 'QUESTION', '["MSA", "전환"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16408 MINUTE)),
  (8, '건조기 추천 부탁합니다', 'Spring Batch로 천만 건 데이터를 처리하는데 속도가 너무 느립니다. chunk size, 병렬 처리 관련 최적화 방법 알려주세요.', 'QUESTION', '["여행", "서울근교"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1695 MINUTE)),
  (9, '이벤트 소싱 도입 경험', '출퇴근용 전기 자전거 추천해주세요. 편도 5km 정도이고 예산은 100만원 이하입니다.', 'QUESTION', '["IntelliJ", "단축키"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5985 MINUTE)),
  (10, '태블릿 추천해주세요', 'OpenSearch에서 multi_match 쿼리 성능이 느린데 최적화 방법이 있을까요? 인덱스 수천만 건입니다.', 'QUESTION', '["스피커", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15002 MINUTE));
