  (9, 'IntelliJ 유용한 단축키', '서울에서 직장 다니는 사회초년생인데 월세 얼마 정도가 적당한가요? 지역은 2호선 라인 기준입니다.', 'QUESTION', '["IntelliJ", "단축키"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18888 MINUTE)),
  (10, '블루투스 스피커 추천해주세요', 'JPA에서 N+1 문제가 발생하는데 fetch join 말고 다른 해결 방법이 있을까요? BatchSize, EntityGraph 등 비교해주세요.', 'QUESTION', '["스피커", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26244 MINUTE)),
  (1, 'WebFlux vs MVC 선택 기준', '출퇴근용 무선 이어폰 추천해주세요. 예산 15만원 이하, 노이즈캔슬링 있으면 좋겠습니다.', 'QUESTION', '["Docker", "네트워크"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36051 MINUTE)),
  (2, '자취 필수 가전 추천', 'Spring Security 6에서 SecurityFilterChain 설정하는데 자꾸 403이 나옵니다. CSRF 비활성화도 했는데 뭐가 문제일까요?', 'QUESTION', '["Kotlin", "coroutine"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 2404 MINUTE)),
  (3, 'CI/CD 파이프라인 구성 질문', '전세 대출 받아서 전세 사는 게 나을까요, 아니면 월세가 나을까요? 보증금 5천에 월세 70 vs 전세 2억 기준입니다.', 'QUESTION', '["맥북", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29807 MINUTE)),
  (4, '노이즈캔슬링 이어폰 추천', 'Redis를 캐시로 사용할 때 cache-aside vs write-through vs write-behind 각각 어떤 상황에서 써야 하나요?', 'QUESTION', '["월세", "서울"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5771 MINUTE)),
  (5, 'JVM 메모리 튜닝 방법', '헬스장을 처음 가보려는데 뭐부터 하면 좋을까요? 운동 루틴이나 주의사항 알려주세요.', 'QUESTION', '["JPA", "N+1"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20612 MINUTE)),
  (6, '맛있는 밀키트 추천해주세요', 'Git 브랜치 전략으로 Git Flow vs GitHub Flow vs Trunk-Based 중 뭐가 좋은가요? 팀 규모 5명입니다.', 'QUESTION', '["이어폰", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16541 MINUTE)),
  (7, 'Terraform vs CloudFormation', '식기세척기 구매를 고민 중인데 빌트인 vs 프리스탠딩 장단점 알려주세요. 자취 원룸입니다.', 'QUESTION', '["Spring", "Security"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21186 MINUTE)),
  (8, '인덕션 vs 가스레인지', 'Kafka consumer lag이 계속 쌓이고 있는데 파티션 수 늘리는 것 외에 다른 방법이 있을까요?', 'QUESTION', '["전세", "월세"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7597 MINUTE)),
  (9, 'gRPC 도입 경험 있으신가요', '처음 해외여행 가는데 준비물이 뭐가 필요한가요? 여권 발급은 했고 일본 3박 4일 예정입니다.', 'QUESTION', '["Redis", "캐시"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26488 MINUTE)),
  (10, '로봇청소기 추천 부탁드립니다', 'MySQL에서 복합 인덱스를 설계할 때 컬럼 순서를 어떻게 정해야 하나요? WHERE, ORDER BY, GROUP BY 조합별로 알려주세요.', 'QUESTION', '["헬스", "입문"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33724 MINUTE)),
  (1, '효율적인 코드 리뷰 방법', '방 크기 10평 정도인데 공기청정기 추천해주세요. 미세먼지 심한 날 효과 있나요?', 'QUESTION', '["Git", "브랜치"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 75 MINUTE)),
  (2, '서울 맛집 추천해주세요', 'REST API로 잘 쓰고 있는데 GraphQL로 전환할 이유가 있을까요? 프론트엔드 팀이 요청하는 중입니다.', 'QUESTION', '["식세기", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 43100 MINUTE)),
  (3, 'Gradle 빌드 속도 개선 방법', '자취를 시작하려는데 원룸이 나을까요 투룸이 나을까요? 예산 월세 60만원 기준입니다.', 'QUESTION', '["Kafka", "consumer"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35559 MINUTE)),
  (4, '캠핑 입문 장비 추천', 'Kubernetes에서 pod가 OOMKilled로 자꾸 재시작됩니다. 메모리 limit을 올리는 것 외에 방법이 있을까요?', 'QUESTION', '["해외여행", "준비"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30276 MINUTE)),
  (5, 'ElasticSearch 클러스터 설계', '집에서 쓸 커피 머신 추천해주세요. 캡슐 vs 반자동 vs 전자동 장단점 알려주시면 감사하겠습니다.', 'QUESTION', '["MySQL", "인덱스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27082 MINUTE)),
  (6, '겨울 패딩 추천해주세요', '서버리스(Lambda)와 EC2 중 어떤 상황에서 뭘 써야 하나요? 현재 트래픽이 불규칙한 API 서버를 운영 중입니다.', 'QUESTION', '["공기청정기", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3552 MINUTE)),
  (7, 'Spring Cloud Gateway 질문', '여름철 제습기 추천해주세요. 방 크기 8평 기준이고 예산은 30만원 이하입니다.', 'QUESTION', '["REST", "GraphQL"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12293 MINUTE)),
  (8, '건조기 추천 부탁합니다', 'Spring Batch로 천만 건 데이터를 처리하는데 속도가 너무 느립니다. chunk size, 병렬 처리 관련 최적화 방법 알려주세요.', 'QUESTION', '["원룸", "자취"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33976 MINUTE)),
  (9, '이벤트 소싱 도입 경험', '출퇴근용 전기 자전거 추천해주세요. 편도 5km 정도이고 예산은 100만원 이하입니다.', 'QUESTION', '["Kubernetes", "OOM"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23709 MINUTE)),
  (10, '태블릿 추천해주세요', 'OpenSearch에서 multi_match 쿼리 성능이 느린데 최적화 방법이 있을까요? 인덱스 수천만 건입니다.', 'QUESTION', '["커피머신", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40804 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, 'AI가 개발자를 대체할 수 있을까', 'ChatGPT, Copilot 등 AI 도구가 빠르게 발전하고 있는데, 실제로 개발자의 역할이 줄어들까요? 아니면 오히려 생산성 도구로 더 중요해질까요?', 'DISCUSSION', '["AI", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32669 MINUTE)),
  (2, '주 4일 근무제에 대한 의견', '주 4일 근무를 도입한 회사들이 늘어나고 있는데 실제로 생산성이 유지될까요? 경험이 있으신 분 의견 부탁드립니다.', 'DISCUSSION', '["주4일", "근무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40986 MINUTE)),
  (3, '재택근무 vs 출근 어떤 게 나을까', '코로나 이후 재택근무가 보편화되었는데, 여전히 출근이 더 나은 점이 있다고 생각하시나요? 각각의 장단점에 대해 이야기해봅시다.', 'DISCUSSION', '["재택", "출근"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28969 MINUTE)),
  (4, '코딩 테스트가 실무 능력을 평가할 수 있는가', '코딩 테스트로 개발자의 실무 능력을 제대로 평가할 수 있을까요? 알고리즘 문제 풀이가 실제 업무와 얼마나 관련이 있는지 토론해봅시다.', 'DISCUSSION', '["코딩테스트", "채용"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3382 MINUTE)),
  (5, 'MZ세대 직장 문화에 대해', '소위 MZ세대의 직장 문화가 기존 세대와 충돌하는 부분이 있는데, 이에 대한 다양한 시각을 듣고 싶습니다.', 'DISCUSSION', '["MZ세대", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13340 MINUTE)),
  (6, '오픈소스 기여 vs 사이드 프로젝트', '커리어 성장에 오픈소스 기여와 사이드 프로젝트 중 어떤 게 더 도움이 될까요? 각각의 장점에 대해 이야기해봅시다.', 'DISCUSSION', '["오픈소스", "사이드프로젝트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17501 MINUTE)),
  (7, 'TDD는 실무에서 현실적인가', 'TDD를 실무에 적용하고 계신 분 있나요? 이론적으로는 좋은데 일정 압박 속에서 현실적으로 가능한지 의견 나눠봅시다.', 'DISCUSSION', '["TDD", "실무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35993 MINUTE)),
  (8, '연봉 공개 문화에 대한 찬반', '직장에서 연봉을 공개하는 문화에 대해 어떻게 생각하시나요? 투명성 vs 개인 프라이버시, 찬반 의견 부탁드립니다.', 'DISCUSSION', '["연봉", "공개"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8586 MINUTE)),
  (9, '개발자 블로그 운영의 가치', '개발자 블로그를 운영하는 것이 커리어에 얼마나 도움이 되나요? 시간 투자 대비 가치가 있는지 이야기해봅시다.', 'DISCUSSION', '["블로그", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18876 MINUTE)),
  (10, '기술 부채를 어떻게 관리해야 하는가', '기술 부채가 쌓이는 건 어쩔 수 없는 건데, 어떻게 관리하고 갚아나가야 할까요? 실무 경험 공유 부탁드립니다.', 'DISCUSSION', '["기술부채", "관리"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28712 MINUTE)),
  (1, '모놀리스 vs MSA 실무 경험', '모놀리스에서 MSA로 전환한 경험이 있으신 분 계신가요? 실제로 장점이 단점보다 크셨나요?', 'DISCUSSION', '["모놀리스", "MSA"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31766 MINUTE)),
  (2, '주니어 개발자 채용 기준', '주니어 개발자를 채용할 때 어떤 점을 가장 중요하게 보시나요? 기술력, 학습 능력, 커뮤니케이션 등 다양한 의견을 듣고 싶습니다.', 'DISCUSSION', '["주니어", "채용"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7957 MINUTE)),
  (3, '야근 문화 언제 없어질까', '한국 IT 업계의 야근 문화가 점점 줄어들고 있다고는 하지만 아직도 만연한 곳이 많습니다. 근본적인 원인과 해결 방법에 대해 토론해봅시다.', 'DISCUSSION', '["야근", "문화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1891 MINUTE)),
  (4, '대학 전공이 실무에서 중요한가', '컴퓨터 과학 전공이 실무에서 얼마나 중요하다고 생각하시나요? 비전공 출신 개발자도 많은데 전공의 실질적 가치가 있는지 논의해봅시다.', 'DISCUSSION', '["전공", "비전공"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41289 MINUTE)),
  (5, '코드 소유권에 대한 의견', '팀에서 특정 코드의 소유권을 한 사람이 가지는 것이 좋은가요, 아니면 전체가 공유하는 것이 좋은가요?', 'DISCUSSION', '["코드", "소유권"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39903 MINUTE)),
  (6, '개발자에게 영어가 얼마나 중요한가', '개발자에게 영어 능력이 얼마나 중요한지 이야기해봅시다. 공식 문서, 오류 메시지, 해외 커뮤니티 참여 등을 고려하면 필수인 것 같기도 합니다.', 'DISCUSSION', '["영어", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15682 MINUTE)),
  (7, '스타트업 vs 대기업 개발 문화', '스타트업과 대기업의 개발 문화 차이에 대해 경험을 공유해주세요. 각각 어떤 장단점이 있었나요?', 'DISCUSSION', '["스타트업", "대기업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10379 MINUTE)),
  (8, '기술 블로그 글감 고갈에 대해', '기술 블로그를 꾸준히 운영하시는 분들, 글감 고갈을 어떻게 해결하시나요? 블로그 운영 노하우를 공유해주세요.', 'DISCUSSION', '["블로그", "글감"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20365 MINUTE)),
  (9, '개발자 커뮤니티의 역할', '개발자 커뮤니티(밋업, 컨퍼런스, 온라인 포럼)가 개인 성장에 얼마나 도움이 되시나요?', 'DISCUSSION', '["커뮤니티", "성장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36099 MINUTE)),
  (10, '자격증이 취업에 도움이 되나', '정보처리기사, AWS 자격증 등이 실제 취업이나 이직에 도움이 되나요? 자격증의 실효성에 대해 토론해봅시다.', 'DISCUSSION', '["자격증", "취업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 896 MINUTE)),
  (1, '리모트 워크의 미래', '리모트 워크가 앞으로도 지속될까요? 아니면 결국 오피스로 돌아가게 될까요? 미래의 근무 형태에 대해 이야기해봅시다.', 'DISCUSSION', '["리모트", "근무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36192 MINUTE)),
  (2, '개발자의 소프트 스킬', '개발자에게 소프트 스킬(커뮤니케이션, 리더십, 협업)이 기술 역량만큼 중요하다고 생각하시나요?', 'DISCUSSION', '["소프트스킬", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26738 MINUTE)),
  (3, '오픈소스 라이선스 이해의 중요성', '오픈소스 프로젝트를 사용할 때 라이선스를 제대로 이해하고 사용하시나요? MIT, Apache, GPL 등 차이를 알아야 하는 이유에 대해 논의해봅시다.', 'DISCUSSION', '["오픈소스", "라이선스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6108 MINUTE)),
  (4, '프레임워크 vs 라이브러리 선택 기준', '새 프로젝트를 시작할 때 프레임워크와 라이브러리를 어떤 기준으로 선택하시나요?', 'DISCUSSION', '["프레임워크", "선택"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14725 MINUTE)),
  (5, '사수 없는 환경에서 성장하는 법', '사수나 멘토 없이 성장해야 하는 환경에서 어떻게 효율적으로 학습하시나요? 경험 공유 부탁드립니다.', 'DISCUSSION', '["성장", "학습"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7435 MINUTE)),
  (6, 'IT 업계 성별 다양성', 'ChatGPT, Copilot 등 AI 도구가 빠르게 발전하고 있는데, 실제로 개발자의 역할이 줄어들까요? 아니면 오히려 생산성 도구로 더 중요해질까요?', 'DISCUSSION', '["다양성", "IT"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30241 MINUTE)),
  (7, '개발자 번아웃의 원인과 해결', '주 4일 근무를 도입한 회사들이 늘어나고 있는데 실제로 생산성이 유지될까요? 경험이 있으신 분 의견 부탁드립니다.', 'DISCUSSION', '["번아웃", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7698 MINUTE)),
  (8, '코드 리뷰 문화 정착 방법', '코로나 이후 재택근무가 보편화되었는데, 여전히 출근이 더 나은 점이 있다고 생각하시나요? 각각의 장단점에 대해 이야기해봅시다.', 'DISCUSSION', '["코드리뷰", "문화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42448 MINUTE)),
  (9, '기술 트렌드를 따라가야 하는가', '코딩 테스트로 개발자의 실무 능력을 제대로 평가할 수 있을까요? 알고리즘 문제 풀이가 실제 업무와 얼마나 관련이 있는지 토론해봅시다.', 'DISCUSSION', '["트렌드", "기술"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10090 MINUTE)),
  (10, '개발자의 워라밸', '소위 MZ세대의 직장 문화가 기존 세대와 충돌하는 부분이 있는데, 이에 대한 다양한 시각을 듣고 싶습니다.', 'DISCUSSION', '["워라밸", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32661 MINUTE)),
  (1, '프로그래밍 언어 선택의 기준', '커리어 성장에 오픈소스 기여와 사이드 프로젝트 중 어떤 게 더 도움이 될까요? 각각의 장점에 대해 이야기해봅시다.', 'DISCUSSION', '["AI", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19127 MINUTE)),
  (2, 'DevOps 문화 도입의 어려움', 'TDD를 실무에 적용하고 계신 분 있나요? 이론적으로는 좋은데 일정 압박 속에서 현실적으로 가능한지 의견 나눠봅시다.', 'DISCUSSION', '["주4일", "근무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33349 MINUTE)),
  (3, '신입 개발자 온보딩 방법', '직장에서 연봉을 공개하는 문화에 대해 어떻게 생각하시나요? 투명성 vs 개인 프라이버시, 찬반 의견 부탁드립니다.', 'DISCUSSION', '["재택", "출근"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17919 MINUTE)),
  (4, '기술 면접 프로세스 개선', '개발자 블로그를 운영하는 것이 커리어에 얼마나 도움이 되나요? 시간 투자 대비 가치가 있는지 이야기해봅시다.', 'DISCUSSION', '["코딩테스트", "채용"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27229 MINUTE)),
  (5, '페어 프로그래밍의 장단점', '기술 부채가 쌓이는 건 어쩔 수 없는 건데, 어떻게 관리하고 갚아나가야 할까요? 실무 경험 공유 부탁드립니다.', 'DISCUSSION', '["MZ세대", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31621 MINUTE)),
  (6, '문서화의 중요성', '모놀리스에서 MSA로 전환한 경험이 있으신 분 계신가요? 실제로 장점이 단점보다 크셨나요?', 'DISCUSSION', '["오픈소스", "사이드프로젝트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30947 MINUTE)),
  (7, '레거시 코드와 공존하는 법', '주니어 개발자를 채용할 때 어떤 점을 가장 중요하게 보시나요? 기술력, 학습 능력, 커뮤니케이션 등 다양한 의견을 듣고 싶습니다.', 'DISCUSSION', '["TDD", "실무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15973 MINUTE)),
  (8, '개발자 평가 기준', '한국 IT 업계의 야근 문화가 점점 줄어들고 있다고는 하지만 아직도 만연한 곳이 많습니다. 근본적인 원인과 해결 방법에 대해 토론해봅시다.', 'DISCUSSION', '["연봉", "공개"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29935 MINUTE)),
  (9, '클라우드 vendor lock-in 문제', '컴퓨터 과학 전공이 실무에서 얼마나 중요하다고 생각하시나요? 비전공 출신 개발자도 많은데 전공의 실질적 가치가 있는지 논의해봅시다.', 'DISCUSSION', '["블로그", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36127 MINUTE)),
  (10, '개발 조직의 이상적인 구조', '팀에서 특정 코드의 소유권을 한 사람이 가지는 것이 좋은가요, 아니면 전체가 공유하는 것이 좋은가요?', 'DISCUSSION', '["기술부채", "관리"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9479 MINUTE)),
  (1, '생성형 AI와 저작권 문제', '개발자에게 영어 능력이 얼마나 중요한지 이야기해봅시다. 공식 문서, 오류 메시지, 해외 커뮤니티 참여 등을 고려하면 필수인 것 같기도 합니다.', 'DISCUSSION', '["모놀리스", "MSA"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25138 MINUTE)),
  (2, '오프라인 모임의 가치', '스타트업과 대기업의 개발 문화 차이에 대해 경험을 공유해주세요. 각각 어떤 장단점이 있었나요?', 'DISCUSSION', '["주니어", "채용"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12491 MINUTE)),
  (3, '컨퍼런스 발표의 의미', '기술 블로그를 꾸준히 운영하시는 분들, 글감 고갈을 어떻게 해결하시나요? 블로그 운영 노하우를 공유해주세요.', 'DISCUSSION', '["야근", "문화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39280 MINUTE)),
  (4, '개발자의 사회적 책임', '개발자 커뮤니티(밋업, 컨퍼런스, 온라인 포럼)가 개인 성장에 얼마나 도움이 되시나요?', 'DISCUSSION', '["전공", "비전공"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33308 MINUTE)),
  (5, '기술 선택의 보수성 vs 혁신성', '정보처리기사, AWS 자격증 등이 실제 취업이나 이직에 도움이 되나요? 자격증의 실효성에 대해 토론해봅시다.', 'DISCUSSION', '["코드", "소유권"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8946 MINUTE)),
  (6, '원격 팀의 소통 방법', '리모트 워크가 앞으로도 지속될까요? 아니면 결국 오피스로 돌아가게 될까요? 미래의 근무 형태에 대해 이야기해봅시다.', 'DISCUSSION', '["영어", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4575 MINUTE)),
  (7, '시니어 개발자의 역할', '개발자에게 소프트 스킬(커뮤니케이션, 리더십, 협업)이 기술 역량만큼 중요하다고 생각하시나요?', 'DISCUSSION', '["스타트업", "대기업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18104 MINUTE)),
  (8, '기술 커뮤니티 독성 문화', '오픈소스 프로젝트를 사용할 때 라이선스를 제대로 이해하고 사용하시나요? MIT, Apache, GPL 등 차이를 알아야 하는 이유에 대해 논의해봅시다.', 'DISCUSSION', '["블로그", "글감"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27193 MINUTE)),
  (9, 'AI 시대의 개발자 역할 변화', '새 프로젝트를 시작할 때 프레임워크와 라이브러리를 어떤 기준으로 선택하시나요?', 'DISCUSSION', '["커뮤니티", "성장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22274 MINUTE)),
  (10, '오픈소스 메인테이너의 번아웃', '사수나 멘토 없이 성장해야 하는 환경에서 어떻게 효율적으로 학습하시나요? 경험 공유 부탁드립니다.', 'DISCUSSION', '["자격증", "취업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 33275 MINUTE));
