  (4, '프레임워크 vs 라이브러리 선택 기준', '새 프로젝트를 시작할 때 프레임워크와 라이브러리를 어떤 기준으로 선택하시나요?', 'DISCUSSION', '["전공", "비전공"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26920 MINUTE)),
  (5, '사수 없는 환경에서 성장하는 법', '사수나 멘토 없이 성장해야 하는 환경에서 어떻게 효율적으로 학습하시나요? 경험 공유 부탁드립니다.', 'DISCUSSION', '["코드", "소유권"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 2860 MINUTE)),
  (6, 'IT 업계 성별 다양성', 'ChatGPT, Copilot 등 AI 도구가 빠르게 발전하고 있는데, 실제로 개발자의 역할이 줄어들까요? 아니면 오히려 생산성 도구로 더 중요해질까요?', 'DISCUSSION', '["영어", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20852 MINUTE)),
  (7, '개발자 번아웃의 원인과 해결', '주 4일 근무를 도입한 회사들이 늘어나고 있는데 실제로 생산성이 유지될까요? 경험이 있으신 분 의견 부탁드립니다.', 'DISCUSSION', '["스타트업", "대기업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30996 MINUTE)),
  (8, '코드 리뷰 문화 정착 방법', '코로나 이후 재택근무가 보편화되었는데, 여전히 출근이 더 나은 점이 있다고 생각하시나요? 각각의 장단점에 대해 이야기해봅시다.', 'DISCUSSION', '["블로그", "글감"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 24984 MINUTE)),
  (9, '기술 트렌드를 따라가야 하는가', '코딩 테스트로 개발자의 실무 능력을 제대로 평가할 수 있을까요? 알고리즘 문제 풀이가 실제 업무와 얼마나 관련이 있는지 토론해봅시다.', 'DISCUSSION', '["커뮤니티", "성장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25302 MINUTE)),
  (10, '개발자의 워라밸', '소위 MZ세대의 직장 문화가 기존 세대와 충돌하는 부분이 있는데, 이에 대한 다양한 시각을 듣고 싶습니다.', 'DISCUSSION', '["자격증", "취업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42730 MINUTE)),
  (1, '프로그래밍 언어 선택의 기준', '커리어 성장에 오픈소스 기여와 사이드 프로젝트 중 어떤 게 더 도움이 될까요? 각각의 장점에 대해 이야기해봅시다.', 'DISCUSSION', '["리모트", "근무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9968 MINUTE)),
  (2, 'DevOps 문화 도입의 어려움', 'TDD를 실무에 적용하고 계신 분 있나요? 이론적으로는 좋은데 일정 압박 속에서 현실적으로 가능한지 의견 나눠봅시다.', 'DISCUSSION', '["소프트스킬", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32461 MINUTE)),
  (3, '신입 개발자 온보딩 방법', '직장에서 연봉을 공개하는 문화에 대해 어떻게 생각하시나요? 투명성 vs 개인 프라이버시, 찬반 의견 부탁드립니다.', 'DISCUSSION', '["오픈소스", "라이선스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 2426 MINUTE)),
  (4, '기술 면접 프로세스 개선', '개발자 블로그를 운영하는 것이 커리어에 얼마나 도움이 되나요? 시간 투자 대비 가치가 있는지 이야기해봅시다.', 'DISCUSSION', '["프레임워크", "선택"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8273 MINUTE)),
  (5, '페어 프로그래밍의 장단점', '기술 부채가 쌓이는 건 어쩔 수 없는 건데, 어떻게 관리하고 갚아나가야 할까요? 실무 경험 공유 부탁드립니다.', 'DISCUSSION', '["성장", "학습"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32918 MINUTE)),
  (6, '문서화의 중요성', '모놀리스에서 MSA로 전환한 경험이 있으신 분 계신가요? 실제로 장점이 단점보다 크셨나요?', 'DISCUSSION', '["다양성", "IT"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38678 MINUTE)),
  (7, '레거시 코드와 공존하는 법', '주니어 개발자를 채용할 때 어떤 점을 가장 중요하게 보시나요? 기술력, 학습 능력, 커뮤니케이션 등 다양한 의견을 듣고 싶습니다.', 'DISCUSSION', '["번아웃", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21757 MINUTE)),
  (8, '개발자 평가 기준', '한국 IT 업계의 야근 문화가 점점 줄어들고 있다고는 하지만 아직도 만연한 곳이 많습니다. 근본적인 원인과 해결 방법에 대해 토론해봅시다.', 'DISCUSSION', '["코드리뷰", "문화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6577 MINUTE)),
  (9, '클라우드 vendor lock-in 문제', '컴퓨터 과학 전공이 실무에서 얼마나 중요하다고 생각하시나요? 비전공 출신 개발자도 많은데 전공의 실질적 가치가 있는지 논의해봅시다.', 'DISCUSSION', '["트렌드", "기술"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28855 MINUTE)),
  (10, '개발 조직의 이상적인 구조', '팀에서 특정 코드의 소유권을 한 사람이 가지는 것이 좋은가요, 아니면 전체가 공유하는 것이 좋은가요?', 'DISCUSSION', '["워라밸", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6534 MINUTE)),
  (1, '생성형 AI와 저작권 문제', '개발자에게 영어 능력이 얼마나 중요한지 이야기해봅시다. 공식 문서, 오류 메시지, 해외 커뮤니티 참여 등을 고려하면 필수인 것 같기도 합니다.', 'DISCUSSION', '["AI", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 34468 MINUTE)),
  (2, '오프라인 모임의 가치', '스타트업과 대기업의 개발 문화 차이에 대해 경험을 공유해주세요. 각각 어떤 장단점이 있었나요?', 'DISCUSSION', '["주4일", "근무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29945 MINUTE)),
  (3, '컨퍼런스 발표의 의미', '기술 블로그를 꾸준히 운영하시는 분들, 글감 고갈을 어떻게 해결하시나요? 블로그 운영 노하우를 공유해주세요.', 'DISCUSSION', '["재택", "출근"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1005 MINUTE)),
  (4, '개발자의 사회적 책임', '개발자 커뮤니티(밋업, 컨퍼런스, 온라인 포럼)가 개인 성장에 얼마나 도움이 되시나요?', 'DISCUSSION', '["코딩테스트", "채용"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9447 MINUTE)),
  (5, '기술 선택의 보수성 vs 혁신성', '정보처리기사, AWS 자격증 등이 실제 취업이나 이직에 도움이 되나요? 자격증의 실효성에 대해 토론해봅시다.', 'DISCUSSION', '["MZ세대", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26868 MINUTE)),
  (6, '원격 팀의 소통 방법', '리모트 워크가 앞으로도 지속될까요? 아니면 결국 오피스로 돌아가게 될까요? 미래의 근무 형태에 대해 이야기해봅시다.', 'DISCUSSION', '["오픈소스", "사이드프로젝트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42911 MINUTE)),
  (7, '시니어 개발자의 역할', '개발자에게 소프트 스킬(커뮤니케이션, 리더십, 협업)이 기술 역량만큼 중요하다고 생각하시나요?', 'DISCUSSION', '["TDD", "실무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10116 MINUTE)),
  (8, '기술 커뮤니티 독성 문화', '오픈소스 프로젝트를 사용할 때 라이선스를 제대로 이해하고 사용하시나요? MIT, Apache, GPL 등 차이를 알아야 하는 이유에 대해 논의해봅시다.', 'DISCUSSION', '["연봉", "공개"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4903 MINUTE)),
  (9, 'AI 시대의 개발자 역할 변화', '새 프로젝트를 시작할 때 프레임워크와 라이브러리를 어떤 기준으로 선택하시나요?', 'DISCUSSION', '["블로그", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30768 MINUTE)),
  (10, '오픈소스 메인테이너의 번아웃', '사수나 멘토 없이 성장해야 하는 환경에서 어떻게 효율적으로 학습하시나요? 경험 공유 부탁드립니다.', 'DISCUSSION', '["기술부채", "관리"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17368 MINUTE));
