  (3, '야근 문화 언제 없어질까', '한국 IT 업계의 야근 문화가 점점 줄어들고 있다고는 하지만 아직도 만연한 곳이 많습니다. 근본적인 원인과 해결 방법에 대해 토론해봅시다.', 'DISCUSSION', '["야근", "문화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4840 MINUTE)),
  (4, '대학 전공이 실무에서 중요한가', '컴퓨터 과학 전공이 실무에서 얼마나 중요하다고 생각하시나요? 비전공 출신 개발자도 많은데 전공의 실질적 가치가 있는지 논의해봅시다.', 'DISCUSSION', '["전공", "비전공"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28949 MINUTE)),
  (5, '코드 소유권에 대한 의견', '팀에서 특정 코드의 소유권을 한 사람이 가지는 것이 좋은가요, 아니면 전체가 공유하는 것이 좋은가요?', 'DISCUSSION', '["코드", "소유권"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22646 MINUTE)),
  (6, '개발자에게 영어가 얼마나 중요한가', '개발자에게 영어 능력이 얼마나 중요한지 이야기해봅시다. 공식 문서, 오류 메시지, 해외 커뮤니티 참여 등을 고려하면 필수인 것 같기도 합니다.', 'DISCUSSION', '["영어", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38507 MINUTE)),
  (7, '스타트업 vs 대기업 개발 문화', '스타트업과 대기업의 개발 문화 차이에 대해 경험을 공유해주세요. 각각 어떤 장단점이 있었나요?', 'DISCUSSION', '["스타트업", "대기업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19605 MINUTE)),
  (8, '기술 블로그 글감 고갈에 대해', '기술 블로그를 꾸준히 운영하시는 분들, 글감 고갈을 어떻게 해결하시나요? 블로그 운영 노하우를 공유해주세요.', 'DISCUSSION', '["블로그", "글감"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41873 MINUTE)),
  (9, '개발자 커뮤니티의 역할', '개발자 커뮤니티(밋업, 컨퍼런스, 온라인 포럼)가 개인 성장에 얼마나 도움이 되시나요?', 'DISCUSSION', '["커뮤니티", "성장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27807 MINUTE)),
  (10, '자격증이 취업에 도움이 되나', '정보처리기사, AWS 자격증 등이 실제 취업이나 이직에 도움이 되나요? 자격증의 실효성에 대해 토론해봅시다.', 'DISCUSSION', '["자격증", "취업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16390 MINUTE)),
  (1, '리모트 워크의 미래', '리모트 워크가 앞으로도 지속될까요? 아니면 결국 오피스로 돌아가게 될까요? 미래의 근무 형태에 대해 이야기해봅시다.', 'DISCUSSION', '["리모트", "근무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29939 MINUTE)),
  (2, '개발자의 소프트 스킬', '개발자에게 소프트 스킬(커뮤니케이션, 리더십, 협업)이 기술 역량만큼 중요하다고 생각하시나요?', 'DISCUSSION', '["소프트스킬", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19799 MINUTE)),
  (3, '오픈소스 라이선스 이해의 중요성', '오픈소스 프로젝트를 사용할 때 라이선스를 제대로 이해하고 사용하시나요? MIT, Apache, GPL 등 차이를 알아야 하는 이유에 대해 논의해봅시다.', 'DISCUSSION', '["오픈소스", "라이선스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13055 MINUTE)),
  (4, '프레임워크 vs 라이브러리 선택 기준', '새 프로젝트를 시작할 때 프레임워크와 라이브러리를 어떤 기준으로 선택하시나요?', 'DISCUSSION', '["프레임워크", "선택"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25211 MINUTE)),
  (5, '사수 없는 환경에서 성장하는 법', '사수나 멘토 없이 성장해야 하는 환경에서 어떻게 효율적으로 학습하시나요? 경험 공유 부탁드립니다.', 'DISCUSSION', '["성장", "학습"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31667 MINUTE)),
  (6, 'IT 업계 성별 다양성', 'ChatGPT, Copilot 등 AI 도구가 빠르게 발전하고 있는데, 실제로 개발자의 역할이 줄어들까요? 아니면 오히려 생산성 도구로 더 중요해질까요?', 'DISCUSSION', '["다양성", "IT"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6989 MINUTE)),
  (7, '개발자 번아웃의 원인과 해결', '주 4일 근무를 도입한 회사들이 늘어나고 있는데 실제로 생산성이 유지될까요? 경험이 있으신 분 의견 부탁드립니다.', 'DISCUSSION', '["번아웃", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15545 MINUTE)),
  (8, '코드 리뷰 문화 정착 방법', '코로나 이후 재택근무가 보편화되었는데, 여전히 출근이 더 나은 점이 있다고 생각하시나요? 각각의 장단점에 대해 이야기해봅시다.', 'DISCUSSION', '["코드리뷰", "문화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 24993 MINUTE)),
  (9, '기술 트렌드를 따라가야 하는가', '코딩 테스트로 개발자의 실무 능력을 제대로 평가할 수 있을까요? 알고리즘 문제 풀이가 실제 업무와 얼마나 관련이 있는지 토론해봅시다.', 'DISCUSSION', '["트렌드", "기술"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37481 MINUTE)),
  (10, '개발자의 워라밸', '소위 MZ세대의 직장 문화가 기존 세대와 충돌하는 부분이 있는데, 이에 대한 다양한 시각을 듣고 싶습니다.', 'DISCUSSION', '["워라밸", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23524 MINUTE)),
  (1, '프로그래밍 언어 선택의 기준', '커리어 성장에 오픈소스 기여와 사이드 프로젝트 중 어떤 게 더 도움이 될까요? 각각의 장점에 대해 이야기해봅시다.', 'DISCUSSION', '["AI", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37670 MINUTE)),
  (2, 'DevOps 문화 도입의 어려움', 'TDD를 실무에 적용하고 계신 분 있나요? 이론적으로는 좋은데 일정 압박 속에서 현실적으로 가능한지 의견 나눠봅시다.', 'DISCUSSION', '["주4일", "근무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19390 MINUTE)),
  (3, '신입 개발자 온보딩 방법', '직장에서 연봉을 공개하는 문화에 대해 어떻게 생각하시나요? 투명성 vs 개인 프라이버시, 찬반 의견 부탁드립니다.', 'DISCUSSION', '["재택", "출근"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19348 MINUTE)),
  (4, '기술 면접 프로세스 개선', '개발자 블로그를 운영하는 것이 커리어에 얼마나 도움이 되나요? 시간 투자 대비 가치가 있는지 이야기해봅시다.', 'DISCUSSION', '["코딩테스트", "채용"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1437 MINUTE)),
  (5, '페어 프로그래밍의 장단점', '기술 부채가 쌓이는 건 어쩔 수 없는 건데, 어떻게 관리하고 갚아나가야 할까요? 실무 경험 공유 부탁드립니다.', 'DISCUSSION', '["MZ세대", "직장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 43137 MINUTE)),
  (6, '문서화의 중요성', '모놀리스에서 MSA로 전환한 경험이 있으신 분 계신가요? 실제로 장점이 단점보다 크셨나요?', 'DISCUSSION', '["오픈소스", "사이드프로젝트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 25939 MINUTE)),
  (7, '레거시 코드와 공존하는 법', '주니어 개발자를 채용할 때 어떤 점을 가장 중요하게 보시나요? 기술력, 학습 능력, 커뮤니케이션 등 다양한 의견을 듣고 싶습니다.', 'DISCUSSION', '["TDD", "실무"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17988 MINUTE)),
  (8, '개발자 평가 기준', '한국 IT 업계의 야근 문화가 점점 줄어들고 있다고는 하지만 아직도 만연한 곳이 많습니다. 근본적인 원인과 해결 방법에 대해 토론해봅시다.', 'DISCUSSION', '["연봉", "공개"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 530 MINUTE)),
  (9, '클라우드 vendor lock-in 문제', '컴퓨터 과학 전공이 실무에서 얼마나 중요하다고 생각하시나요? 비전공 출신 개발자도 많은데 전공의 실질적 가치가 있는지 논의해봅시다.', 'DISCUSSION', '["블로그", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37088 MINUTE)),
  (10, '개발 조직의 이상적인 구조', '팀에서 특정 코드의 소유권을 한 사람이 가지는 것이 좋은가요, 아니면 전체가 공유하는 것이 좋은가요?', 'DISCUSSION', '["기술부채", "관리"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3214 MINUTE)),
  (1, '생성형 AI와 저작권 문제', '개발자에게 영어 능력이 얼마나 중요한지 이야기해봅시다. 공식 문서, 오류 메시지, 해외 커뮤니티 참여 등을 고려하면 필수인 것 같기도 합니다.', 'DISCUSSION', '["모놀리스", "MSA"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39741 MINUTE)),
  (2, '오프라인 모임의 가치', '스타트업과 대기업의 개발 문화 차이에 대해 경험을 공유해주세요. 각각 어떤 장단점이 있었나요?', 'DISCUSSION', '["주니어", "채용"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32553 MINUTE)),
  (3, '컨퍼런스 발표의 의미', '기술 블로그를 꾸준히 운영하시는 분들, 글감 고갈을 어떻게 해결하시나요? 블로그 운영 노하우를 공유해주세요.', 'DISCUSSION', '["야근", "문화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18756 MINUTE)),
  (4, '개발자의 사회적 책임', '개발자 커뮤니티(밋업, 컨퍼런스, 온라인 포럼)가 개인 성장에 얼마나 도움이 되시나요?', 'DISCUSSION', '["전공", "비전공"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15081 MINUTE)),
  (5, '기술 선택의 보수성 vs 혁신성', '정보처리기사, AWS 자격증 등이 실제 취업이나 이직에 도움이 되나요? 자격증의 실효성에 대해 토론해봅시다.', 'DISCUSSION', '["코드", "소유권"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39784 MINUTE)),
  (6, '원격 팀의 소통 방법', '리모트 워크가 앞으로도 지속될까요? 아니면 결국 오피스로 돌아가게 될까요? 미래의 근무 형태에 대해 이야기해봅시다.', 'DISCUSSION', '["영어", "개발자"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23089 MINUTE)),
  (7, '시니어 개발자의 역할', '개발자에게 소프트 스킬(커뮤니케이션, 리더십, 협업)이 기술 역량만큼 중요하다고 생각하시나요?', 'DISCUSSION', '["스타트업", "대기업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14352 MINUTE)),
  (8, '기술 커뮤니티 독성 문화', '오픈소스 프로젝트를 사용할 때 라이선스를 제대로 이해하고 사용하시나요? MIT, Apache, GPL 등 차이를 알아야 하는 이유에 대해 논의해봅시다.', 'DISCUSSION', '["블로그", "글감"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41721 MINUTE)),
  (9, 'AI 시대의 개발자 역할 변화', '새 프로젝트를 시작할 때 프레임워크와 라이브러리를 어떤 기준으로 선택하시나요?', 'DISCUSSION', '["커뮤니티", "성장"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12460 MINUTE)),
  (10, '오픈소스 메인테이너의 번아웃', '사수나 멘토 없이 성장해야 하는 환경에서 어떻게 효율적으로 학습하시나요? 경험 공유 부탁드립니다.', 'DISCUSSION', '["자격증", "취업"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40690 MINUTE));
INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, '넷플릭스 신작 드라마 리뷰', '넷플릭스에서 새로 나온 드라마를 정주행했는데 역대급이었습니다. 스토리, 연출, 연기 모두 완벽해요. 스포일러 없이 추천합니다.', 'MEDIA', '["넷플릭스", "드라마"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16425 MINUTE)),
  (2, '올해 본 영화 중 최고', '올해 극장에서 본 영화 중 단연 최고였습니다. 러닝타임이 2시간 30분인데 전혀 지루하지 않았어요. 엔딩 크레딧까지 보셔야 합니다.', 'MEDIA', '["영화", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 43200 MINUTE)),
  (3, '요즘 듣는 플레이리스트 공유', '요즘 출퇴근길에 듣는 플레이리스트 공유합니다. 장르는 인디팝부터 재즈까지 다양하게 넣었어요. 아침에 기분 좋아지는 곡들 위주입니다.', 'MEDIA', '["음악", "플레이리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8963 MINUTE)),
  (4, '신작 게임 후기', '신작 오픈월드 RPG를 50시간 플레이했습니다. 그래픽, 스토리, 전투 시스템 모두 만족스럽고 사이드 퀘스트도 알찹니다.', 'MEDIA', '["게임", "RPG"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41172 MINUTE)),
  (5, '웹툰 추천합니다', '완결 웹툰 중에 꼭 봐야 할 작품을 추천합니다. 스토리가 탄탄하고 작화도 좋아요. 무료로 볼 수 있는 플랫폼도 알려드릴게요.', 'MEDIA', '["웹툰", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6367 MINUTE)),
  (6, '팟캐스트 추천 리스트', '출퇴근길에 듣기 좋은 팟캐스트 추천합니다. IT, 시사, 문화 등 카테고리별로 정리했어요.', 'MEDIA', '["팟캐스트", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41121 MINUTE)),
  (7, '올해의 앨범 추천', '올해 발매된 앨범 중 가장 인상 깊었던 것들을 장르별로 추천합니다. K-POP부터 인디까지 포함했어요.', 'MEDIA', '["앨범", "음악"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42358 MINUTE)),
  (8, '인디 영화 추천', '대형 극장에서는 보기 힘든 인디 영화들 중 숨겨진 명작들을 추천합니다. 짧은 러닝타임에 깊은 여운을 남기는 작품들이에요.', 'MEDIA', '["인디영화", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 2583 MINUTE)),
  (9, '넷플릭스 다큐멘터리 추천', '넷플릭스 다큐멘터리 중 인생 다큐를 소개합니다. 자연, 사회, 범죄 등 다양한 주제별로 정리했어요.', 'MEDIA', '["다큐멘터리", "넷플릭스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20246 MINUTE)),
  (10, '최근 본 애니메이션 후기', '최근 완결된 애니메이션을 봤는데 작화와 연출이 극장판 수준이었습니다. 원작 만화와 비교 리뷰도 함께 올립니다.', 'MEDIA', '["애니메이션", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28889 MINUTE)),
  (1, '유튜브 채널 추천', '구독하면 좋은 유튜브 채널을 카테고리별로 정리했습니다. 교육, 요리, IT, 브이로그 등 다양합니다.', 'MEDIA', '["유튜브", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 2186 MINUTE)),
  (2, '올해 최고의 드라마', '올해 방영된 드라마 중 가장 완성도 높았던 작품 TOP 5를 뽑아봤습니다. 장르별로 하나씩 선정했어요.', 'MEDIA', '["드라마", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37982 MINUTE)),
  (3, '스팀 할인 게임 추천', '스팀 겨울 세일에서 사면 좋을 게임들 추천합니다. 장르별로 가격대, 플레이 타임, 난이도를 정리했어요.', 'MEDIA', '["스팀", "세일"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23911 MINUTE)),
  (4, '음악 페스티벌 후기', '이번 주말에 뮤직 페스티벌 다녀왔는데 날씨도 좋고 라인업도 최고였습니다. 현장 분위기 후기 공유합니다.', 'MEDIA', '["페스티벌", "후기"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8612 MINUTE)),
  (5, 'OTT 서비스 비교', '넷플릭스, 티빙, 왓챠, 웨이브, 쿠팡플레이 OTT 서비스를 콘텐츠 수, 가격, 화질 등 기준으로 비교해봤습니다.', 'MEDIA', '["OTT", "비교"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 5906 MINUTE)),
  (6, '독립 영화제 관람 후기', '독립 영화제에서 본 작품들 후기입니다. 메이저 영화와는 다른 신선한 시각이 인상적이었습니다.', 'MEDIA', '["독립영화", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19340 MINUTE)),
  (7, '보드게임 추천합니다', '모임에서 할 만한 보드게임 추천합니다. 인원수별, 난이도별로 정리했어요. 입문자용부터 마니아용까지.', 'MEDIA', '["보드게임", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21411 MINUTE)),
  (8, '최근 읽은 만화책 후기', '최근 일본 만화를 몇 권 읽었는데 스토리가 정말 좋았습니다. 장르별 추천과 간단한 리뷰를 올립니다.', 'MEDIA', '["만화", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 27230 MINUTE)),
  (9, 'K-POP 신곡 리뷰', '이번 달에 나온 K-POP 신곡들 중 인상적이었던 곡들을 리뷰합니다. 음악적 완성도와 뮤직비디오까지 분석했어요.', 'MEDIA', '["K-POP", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 11510 MINUTE)),
  (10, '전시회 다녀왔습니다', '주말에 미술관 전시를 보고 왔습니다. 현대 미술 전시인데 생각보다 재미있고 인상적이었어요. 관람 팁도 공유합니다.', 'MEDIA', '["전시", "미술관"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13159 MINUTE)),
  (1, '새로 나온 웹소설 추천', '새로 연재 시작한 웹소설 중 초반부터 빠져드는 작품을 소개합니다. 장르는 판타지, 로맨스, 현대물 다양합니다.', 'MEDIA', '["웹소설", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8661 MINUTE)),
  (2, '클래식 음악 입문 가이드', '클래식 음악에 입문하고 싶은 분들을 위한 가이드입니다. 어디서부터 들어야 할지 작곡가, 장르별로 정리했습니다.', 'MEDIA', '["클래식", "입문"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 35350 MINUTE)),
  (3, '영화 OST 추천합니다', '영화에서 들었던 OST 중 인생곡을 모아봤습니다. 영화 장면과 함께 듣으면 더 좋은 곡들이에요.', 'MEDIA', '["OST", "영화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23976 MINUTE)),
  (4, '방탈출 카페 후기', '강남에 있는 방탈출 카페 다녀왔는데 완성도가 높았습니다. 테마별 난이도와 추천 인원을 정리했어요.', 'MEDIA', '["방탈출", "후기"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 34789 MINUTE)),
  (5, '최근 본 뮤지컬 리뷰', '최근 본 뮤지컬이 정말 감동적이었습니다. 배우들의 라이브 가창력이 소름 돋았어요. 좌석 추천까지 포함한 리뷰입니다.', 'MEDIA', '["뮤지컬", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 32885 MINUTE)),
  (6, '게임 사운드트랙 추천', '넷플릭스에서 새로 나온 드라마를 정주행했는데 역대급이었습니다. 스토리, 연출, 연기 모두 완벽해요. 스포일러 없이 추천합니다.', 'MEDIA', '["게임", "사운드트랙"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17860 MINUTE)),
  (7, '해외 드라마 추천', '올해 극장에서 본 영화 중 단연 최고였습니다. 러닝타임이 2시간 30분인데 전혀 지루하지 않았어요. 엔딩 크레딧까지 보셔야 합니다.', 'MEDIA', '["해외드라마", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10783 MINUTE)),
  (8, '책 원작 영화화 비교', '요즘 출퇴근길에 듣는 플레이리스트 공유합니다. 장르는 인디팝부터 재즈까지 다양하게 넣었어요. 아침에 기분 좋아지는 곡들 위주입니다.', 'MEDIA', '["원작", "영화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 16840 MINUTE)),
  (9, 'VR 게임 체험 후기', '신작 오픈월드 RPG를 50시간 플레이했습니다. 그래픽, 스토리, 전투 시스템 모두 만족스럽고 사이드 퀘스트도 알찹니다.', 'MEDIA', '["VR", "게임"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31578 MINUTE)),
  (10, '올해의 웹툰 결산', '완결 웹툰 중에 꼭 봐야 할 작품을 추천합니다. 스토리가 탄탄하고 작화도 좋아요. 무료로 볼 수 있는 플랫폼도 알려드릴게요.', 'MEDIA', '["웹툰", "결산"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19342 MINUTE)),
  (1, '음악 스트리밍 서비스 비교', '출퇴근길에 듣기 좋은 팟캐스트 추천합니다. IT, 시사, 문화 등 카테고리별로 정리했어요.', 'MEDIA', '["넷플릭스", "드라마"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22198 MINUTE)),
  (2, '최근 본 공연 후기', '올해 발매된 앨범 중 가장 인상 깊었던 것들을 장르별로 추천합니다. K-POP부터 인디까지 포함했어요.', 'MEDIA', '["영화", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7547 MINUTE)),
  (3, '레트로 게임 추천', '대형 극장에서는 보기 힘든 인디 영화들 중 숨겨진 명작들을 추천합니다. 짧은 러닝타임에 깊은 여운을 남기는 작품들이에요.', 'MEDIA', '["음악", "플레이리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 30692 MINUTE)),
  (4, '영화 시리즈 정주행 후기', '넷플릭스 다큐멘터리 중 인생 다큐를 소개합니다. 자연, 사회, 범죄 등 다양한 주제별로 정리했어요.', 'MEDIA', '["게임", "RPG"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4934 MINUTE)),
  (5, '힙합 앨범 리뷰', '최근 완결된 애니메이션을 봤는데 작화와 연출이 극장판 수준이었습니다. 원작 만화와 비교 리뷰도 함께 올립니다.', 'MEDIA', '["웹툰", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 9224 MINUTE)),
  (6, '일본 애니메이션 추천', '구독하면 좋은 유튜브 채널을 카테고리별로 정리했습니다. 교육, 요리, IT, 브이로그 등 다양합니다.', 'MEDIA', '["팟캐스트", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14785 MINUTE)),
  (7, 'SF 영화 추천 리스트', '올해 방영된 드라마 중 가장 완성도 높았던 작품 TOP 5를 뽑아봤습니다. 장르별로 하나씩 선정했어요.', 'MEDIA', '["앨범", "음악"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26044 MINUTE)),
  (8, '인디 음악 추천합니다', '스팀 겨울 세일에서 사면 좋을 게임들 추천합니다. 장르별로 가격대, 플레이 타임, 난이도를 정리했어요.', 'MEDIA', '["인디영화", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36524 MINUTE)),
  (9, '예능 프로그램 추천', '이번 주말에 뮤직 페스티벌 다녀왔는데 날씨도 좋고 라인업도 최고였습니다. 현장 분위기 후기 공유합니다.', 'MEDIA', '["다큐멘터리", "넷플릭스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23971 MINUTE)),
