  (6, '팟캐스트 추천 리스트', '출퇴근길에 듣기 좋은 팟캐스트 추천합니다. IT, 시사, 문화 등 카테고리별로 정리했어요.', 'MEDIA', '["독립영화", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3968 MINUTE)),
  (7, '올해의 앨범 추천', '올해 발매된 앨범 중 가장 인상 깊었던 것들을 장르별로 추천합니다. K-POP부터 인디까지 포함했어요.', 'MEDIA', '["보드게임", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 26092 MINUTE)),
  (8, '인디 영화 추천', '대형 극장에서는 보기 힘든 인디 영화들 중 숨겨진 명작들을 추천합니다. 짧은 러닝타임에 깊은 여운을 남기는 작품들이에요.', 'MEDIA', '["만화", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18080 MINUTE)),
  (9, '넷플릭스 다큐멘터리 추천', '넷플릭스 다큐멘터리 중 인생 다큐를 소개합니다. 자연, 사회, 범죄 등 다양한 주제별로 정리했어요.', 'MEDIA', '["K-POP", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 12439 MINUTE)),
  (10, '최근 본 애니메이션 후기', '최근 완결된 애니메이션을 봤는데 작화와 연출이 극장판 수준이었습니다. 원작 만화와 비교 리뷰도 함께 올립니다.', 'MEDIA', '["전시", "미술관"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8005 MINUTE)),
  (1, '유튜브 채널 추천', '구독하면 좋은 유튜브 채널을 카테고리별로 정리했습니다. 교육, 요리, IT, 브이로그 등 다양합니다.', 'MEDIA', '["웹소설", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 29800 MINUTE)),
  (2, '올해 최고의 드라마', '올해 방영된 드라마 중 가장 완성도 높았던 작품 TOP 5를 뽑아봤습니다. 장르별로 하나씩 선정했어요.', 'MEDIA', '["클래식", "입문"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 6007 MINUTE)),
  (3, '스팀 할인 게임 추천', '스팀 겨울 세일에서 사면 좋을 게임들 추천합니다. 장르별로 가격대, 플레이 타임, 난이도를 정리했어요.', 'MEDIA', '["OST", "영화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13900 MINUTE)),
  (4, '음악 페스티벌 후기', '이번 주말에 뮤직 페스티벌 다녀왔는데 날씨도 좋고 라인업도 최고였습니다. 현장 분위기 후기 공유합니다.', 'MEDIA', '["방탈출", "후기"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42054 MINUTE)),
  (5, 'OTT 서비스 비교', '넷플릭스, 티빙, 왓챠, 웨이브, 쿠팡플레이 OTT 서비스를 콘텐츠 수, 가격, 화질 등 기준으로 비교해봤습니다.', 'MEDIA', '["뮤지컬", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 41909 MINUTE)),
  (6, '독립 영화제 관람 후기', '독립 영화제에서 본 작품들 후기입니다. 메이저 영화와는 다른 신선한 시각이 인상적이었습니다.', 'MEDIA', '["게임", "사운드트랙"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39134 MINUTE)),
  (7, '보드게임 추천합니다', '모임에서 할 만한 보드게임 추천합니다. 인원수별, 난이도별로 정리했어요. 입문자용부터 마니아용까지.', 'MEDIA', '["해외드라마", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1399 MINUTE)),
  (8, '최근 읽은 만화책 후기', '최근 일본 만화를 몇 권 읽었는데 스토리가 정말 좋았습니다. 장르별 추천과 간단한 리뷰를 올립니다.', 'MEDIA', '["원작", "영화"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3314 MINUTE)),
  (9, 'K-POP 신곡 리뷰', '이번 달에 나온 K-POP 신곡들 중 인상적이었던 곡들을 리뷰합니다. 음악적 완성도와 뮤직비디오까지 분석했어요.', 'MEDIA', '["VR", "게임"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21856 MINUTE)),
  (10, '전시회 다녀왔습니다', '주말에 미술관 전시를 보고 왔습니다. 현대 미술 전시인데 생각보다 재미있고 인상적이었어요. 관람 팁도 공유합니다.', 'MEDIA', '["웹툰", "결산"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15962 MINUTE)),
  (1, '새로 나온 웹소설 추천', '새로 연재 시작한 웹소설 중 초반부터 빠져드는 작품을 소개합니다. 장르는 판타지, 로맨스, 현대물 다양합니다.', 'MEDIA', '["넷플릭스", "드라마"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 8252 MINUTE)),
  (2, '클래식 음악 입문 가이드', '클래식 음악에 입문하고 싶은 분들을 위한 가이드입니다. 어디서부터 들어야 할지 작곡가, 장르별로 정리했습니다.', 'MEDIA', '["영화", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37000 MINUTE)),
  (3, '영화 OST 추천합니다', '영화에서 들었던 OST 중 인생곡을 모아봤습니다. 영화 장면과 함께 듣으면 더 좋은 곡들이에요.', 'MEDIA', '["음악", "플레이리스트"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13448 MINUTE)),
  (4, '방탈출 카페 후기', '강남에 있는 방탈출 카페 다녀왔는데 완성도가 높았습니다. 테마별 난이도와 추천 인원을 정리했어요.', 'MEDIA', '["게임", "RPG"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 4496 MINUTE)),
  (5, '최근 본 뮤지컬 리뷰', '최근 본 뮤지컬이 정말 감동적이었습니다. 배우들의 라이브 가창력이 소름 돋았어요. 좌석 추천까지 포함한 리뷰입니다.', 'MEDIA', '["웹툰", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36320 MINUTE)),
  (6, '게임 사운드트랙 추천', '넷플릭스에서 새로 나온 드라마를 정주행했는데 역대급이었습니다. 스토리, 연출, 연기 모두 완벽해요. 스포일러 없이 추천합니다.', 'MEDIA', '["팟캐스트", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13576 MINUTE)),
  (7, '해외 드라마 추천', '올해 극장에서 본 영화 중 단연 최고였습니다. 러닝타임이 2시간 30분인데 전혀 지루하지 않았어요. 엔딩 크레딧까지 보셔야 합니다.', 'MEDIA', '["앨범", "음악"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 38429 MINUTE)),
  (8, '책 원작 영화화 비교', '요즘 출퇴근길에 듣는 플레이리스트 공유합니다. 장르는 인디팝부터 재즈까지 다양하게 넣었어요. 아침에 기분 좋아지는 곡들 위주입니다.', 'MEDIA', '["인디영화", "추천"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14152 MINUTE)),
  (9, 'VR 게임 체험 후기', '신작 오픈월드 RPG를 50시간 플레이했습니다. 그래픽, 스토리, 전투 시스템 모두 만족스럽고 사이드 퀘스트도 알찹니다.', 'MEDIA', '["다큐멘터리", "넷플릭스"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 15269 MINUTE)),
  (10, '올해의 웹툰 결산', '완결 웹툰 중에 꼭 봐야 할 작품을 추천합니다. 스토리가 탄탄하고 작화도 좋아요. 무료로 볼 수 있는 플랫폼도 알려드릴게요.', 'MEDIA', '["애니메이션", "리뷰"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 21532 MINUTE)),
