INSERT INTO posts (author_id, title, content, category, tags, status, created_at) VALUES
  (1, '게시판 카테고리 추가 제안', '현재 카테고리가 제한적인데 ''스터디 모집'', ''거래/나눔'' 같은 카테고리를 추가해주시면 좋겠습니다.', 'FEEDBACK', '["자동저장", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 10140 MINUTE)),
  (2, '다크모드 지원 요청', '밤에 글을 읽을 때 눈이 아픈데 다크모드를 지원해주시면 정말 좋겠습니다. 시스템 설정 연동도 되면 완벽할 것 같아요.', 'FEEDBACK', '["오프라인", "지원"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 43039 MINUTE)),
  (3, '모바일 UI 개선 제안', '모바일에서 글 작성할 때 에디터가 불편합니다. 글꼴 크기, 이미지 삽입 등 기능을 개선해주시면 좋겠어요.', 'FEEDBACK', '["다국어", "지원"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 31600 MINUTE)),
  (4, '알림 기능이 필요합니다', '새 댓글이나 좋아요 알림이 없어서 불편합니다. 푸시 알림이나 인앱 알림 기능을 추가해주세요.', 'FEEDBACK', '["통계", "대시보드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14696 MINUTE)),
  (5, '검색 기능 개선 요청', '검색할 때 제목만 검색되는 것 같은데 내용, 태그, 작성자까지 검색 범위를 넓혀주시면 좋겠습니다. 검색 필터도 있으면 좋겠어요.', 'FEEDBACK', '["API", "공개"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7092 MINUTE)),
  (6, '익명 채팅 기능 제안', '익명 게시판에 익명 실시간 채팅 기능이 있으면 좋겠습니다. 1:1 채팅이나 그룹 채팅 모두요.', 'FEEDBACK', '["예약발행", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22945 MINUTE)),
  (7, '프로필 커스터마이징 요청', '프로필에 자기소개, 관심 분야, 프로필 이미지 등 커스터마이징 옵션을 추가해주시면 좋겠습니다.', 'FEEDBACK', '["가이드라인", "커뮤니티"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36455 MINUTE)),
  (8, '글 작성 에디터 개선', '글 작성 시 마크다운이나 리치 텍스트 에디터를 지원해주시면 코드 블록이나 표 작성이 편해질 것 같습니다.', 'FEEDBACK', '["인증", "보안"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 24088 MINUTE)),
  (9, '북마크 기능 추가 요청', '마음에 드는 게시글을 북마크해서 나중에 다시 볼 수 있는 기능이 있으면 좋겠습니다.', 'FEEDBACK', '["피드", "알고리즘"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 7529 MINUTE)),
  (10, '댓글 알림 기능 필요', '내 글에 댓글이 달리면 알림이 왔으면 좋겠습니다. 이메일이나 앱 내 알림 모두 좋습니다.', 'FEEDBACK', '["댓글", "정렬"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 18256 MINUTE)),
  (1, '태그 기반 필터링 요청', '태그를 기반으로 게시글을 필터링할 수 있으면 관심 있는 주제만 모아볼 수 있어서 좋겠습니다.', 'FEEDBACK', '["카테고리", "제안"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 37624 MINUTE)),
  (2, '게시글 정렬 옵션 추가', '현재 최신순 정렬만 되는 것 같은데 인기순, 댓글순, 조회순 등 다양한 정렬 옵션을 추가해주세요.', 'FEEDBACK', '["다크모드", "UI"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 14821 MINUTE)),
  (3, '신고 기능 개선 제안', '부적절한 게시글 신고 시 진행 상황을 알 수 없어서 답답합니다. 신고 처리 현황을 알려주시면 좋겠어요.', 'FEEDBACK', '["모바일", "개선"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 28122 MINUTE)),
  (4, '앱 속도가 느려요', '최근 앱이 많이 느려진 것 같습니다. 특히 게시글 목록을 스크롤할 때 버벅임이 있어요. 성능 개선 부탁드립니다.', 'FEEDBACK', '["알림", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36763 MINUTE)),
  (5, '비밀글 기능 요청', '민감한 내용의 글을 비밀글로 설정할 수 있는 기능이 있으면 좋겠습니다. 특정 조건 충족 시 공개되는 방식으로요.', 'FEEDBACK', '["검색", "개선"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40745 MINUTE)),
  (6, '이미지 업로드 기능 개선', '이미지 업로드 시 용량 제한이 너무 작고, 여러 장을 한번에 올리기 어렵습니다. 드래그 앤 드롭도 지원해주세요.', 'FEEDBACK', '["채팅", "익명"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 40211 MINUTE)),
  (7, '사용자 차단 기능 필요', '불쾌한 사용자를 차단할 수 있는 기능이 필요합니다. 차단하면 해당 사용자의 글과 댓글이 안 보이면 좋겠어요.', 'FEEDBACK', '["프로필", "커스터마이징"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 42119 MINUTE)),
  (8, '인기 게시글 알고리즘 개선', '인기 게시글 기준이 불분명합니다. 조회수, 좋아요, 댓글 수를 종합적으로 고려한 알고리즘이면 좋겠어요.', 'FEEDBACK', '["에디터", "개선"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 36486 MINUTE)),
  (9, '접근성 개선 요청', '시각 장애인 등을 위한 접근성 개선이 필요합니다. 스크린 리더 지원, 고대비 모드, 글꼴 크기 조절 등을 고려해주세요.', 'FEEDBACK', '["북마크", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1720 MINUTE)),
  (10, '마크다운 지원 요청', '개발자 유저가 많으니 마크다운 문법을 지원해주시면 코드 공유가 훨씬 편해질 것 같습니다.', 'FEEDBACK', '["댓글", "알림"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 39911 MINUTE)),
  (1, '자동 저장 기능 필요', '글 작성 중에 브라우저가 꺼지면 내용이 다 날아갑니다. 자동 저장 기능을 추가해주세요.', 'FEEDBACK', '["태그", "필터링"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 43111 MINUTE)),
  (2, '오프라인 모드 지원 요청', '인터넷이 안 되는 환경에서도 저장된 글을 읽을 수 있는 오프라인 모드가 있으면 좋겠습니다.', 'FEEDBACK', '["정렬", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17527 MINUTE)),
  (3, '다국어 지원 요청', '한국어 외에 영어, 일본어 등 다국어 지원을 해주시면 해외 유저도 참여할 수 있을 것 같습니다.', 'FEEDBACK', '["신고", "개선"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 1897 MINUTE)),
  (4, '통계 대시보드 요청', '내가 작성한 글의 조회수, 좋아요 추이 등을 볼 수 있는 통계 대시보드가 있으면 좋겠습니다.', 'FEEDBACK', '["성능", "개선"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 11823 MINUTE)),
  (5, 'API 공개 요청', '커뮤니티 데이터를 활용할 수 있도록 공개 API를 제공해주시면 서드파티 앱 개발이 가능할 것 같습니다.', 'FEEDBACK', '["비밀글", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 17909 MINUTE)),
  (6, '게시글 예약 발행 기능', '현재 카테고리가 제한적인데 ''스터디 모집'', ''거래/나눔'' 같은 카테고리를 추가해주시면 좋겠습니다.', 'FEEDBACK', '["이미지", "업로드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 20249 MINUTE)),
  (7, '커뮤니티 가이드라인 정비', '밤에 글을 읽을 때 눈이 아픈데 다크모드를 지원해주시면 정말 좋겠습니다. 시스템 설정 연동도 되면 완벽할 것 같아요.', 'FEEDBACK', '["차단", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 22270 MINUTE)),
  (8, '2단계 인증 지원 요청', '모바일에서 글 작성할 때 에디터가 불편합니다. 글꼴 크기, 이미지 삽입 등 기능을 개선해주시면 좋겠어요.', 'FEEDBACK', '["알고리즘", "인기"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 23004 MINUTE)),
  (9, '피드 알고리즘 개선', '새 댓글이나 좋아요 알림이 없어서 불편합니다. 푸시 알림이나 인앱 알림 기능을 추가해주세요.', 'FEEDBACK', '["접근성", "개선"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 400 MINUTE)),
