  (2, '사용자 뱃지 시스템 제안', '프로필에 자기소개, 관심 분야, 프로필 이미지 등 커스터마이징 옵션을 추가해주시면 좋겠습니다.', 'FEEDBACK', '["정렬", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 3590 MINUTE)),
  (3, '실시간 알림 기능', '글 작성 시 마크다운이나 리치 텍스트 에디터를 지원해주시면 코드 블록이나 표 작성이 편해질 것 같습니다.', 'FEEDBACK', '["신고", "개선"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 503 MINUTE)),
  (4, '게시글 공유 기능 개선', '마음에 드는 게시글을 북마크해서 나중에 다시 볼 수 있는 기능이 있으면 좋겠습니다.', 'FEEDBACK', '["성능", "개선"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13397 MINUTE)),
  (5, '스팸 필터링 강화 요청', '내 글에 댓글이 달리면 알림이 왔으면 좋겠습니다. 이메일이나 앱 내 알림 모두 좋습니다.', 'FEEDBACK', '["비밀글", "기능"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 19753 MINUTE)),
  (6, '회원 등급 시스템 제안', '태그를 기반으로 게시글을 필터링할 수 있으면 관심 있는 주제만 모아볼 수 있어서 좋겠습니다.', 'FEEDBACK', '["이미지", "업로드"]', 'PUBLISHED', DATE_SUB(NOW(), INTERVAL 13843 MINUTE)),
