INSERT INTO comments (post_id, author_id, content, parent_comment_id, depth, status) VALUES
  (1, 3, '완전 공감합니다. 저도 비슷한 경험이 있어요.', NULL, 0, 'ACTIVE'),
  (1, 5, '좋은 글이네요! 힘내세요.', NULL, 0, 'ACTIVE'),
  (1, 7, '저도 오늘 비슷한 하루를 보냈어요 ㅋㅋ', NULL, 0, 'ACTIVE'),
  (5, 2, '이직은 신중하게 결정하세요. 저는 이직 후 만족하고 있습니다.', NULL, 0, 'ACTIVE'),
  (5, 8, '3년차면 이직하기 좋은 타이밍이에요.', NULL, 0, 'ACTIVE'),
  (5, 4, '연봉도 중요하지만 성장 환경이 더 중요한 것 같아요.', NULL, 0, 'ACTIVE'),
  (10, 1, 'ㅋㅋㅋㅋ 진짜 웃기네요', NULL, 0, 'ACTIVE'),
  (10, 6, '이거 실화인가요? 너무 웃겨요 ㅋㅋㅋ', NULL, 0, 'ACTIVE'),
  (15, 9, '정보 감사합니다! 북마크해둡니다.', NULL, 0, 'ACTIVE'),
  (15, 3, '이거 진짜 유용한 정보네요. 공유 감사합니다.', NULL, 0, 'ACTIVE'),
  (15, 10, '저도 써봤는데 효과 있었어요!', NULL, 0, 'ACTIVE'),
  (20, 1, 'Docker 네트워크는 bridge 모드 쓰면 됩니다.', NULL, 0, 'ACTIVE'),
  (20, 4, 'docker-compose에서 같은 네트워크로 묶으면 서비스 이름으로 통신 가능해요.', NULL, 0, 'ACTIVE'),
  (25, 6, '좋은 토론 주제네요. 저는 AI가 보조 도구로 남을 거라고 봅니다.', NULL, 0, 'ACTIVE'),
  (25, 2, '개발자의 역할이 바뀔 뿐 대체되진 않을 것 같아요.', NULL, 0, 'ACTIVE'),
  (25, 8, 'AI 도구를 잘 활용하는 개발자가 살아남을 거라고 생각합니다.', NULL, 0, 'ACTIVE'),
  (30, 7, '이 드라마 저도 봤는데 정말 명작이에요!', NULL, 0, 'ACTIVE'),
  (30, 3, '추천 감사합니다. 오늘 밤에 정주행 해야겠어요.', NULL, 0, 'ACTIVE'),
  (35, 5, '다크모드 진짜 필요합니다. 빨리 추가해주세요!', NULL, 0, 'ACTIVE'),
  (35, 9, '다크모드 + 시스템 연동이면 최고일 것 같아요.', NULL, 0, 'ACTIVE'),
  (50, 1, '저도 이거 궁금했어요. 답변 기다리겠습니다.', NULL, 0, 'ACTIVE'),
  (50, 10, '경험상 이렇게 하면 해결됩니다. 참고하세요!', NULL, 0, 'ACTIVE'),
